  function wireForkBand(home) {
    const root = $("#fork-band");
    if (!root) return;
    const cc = String(HOME_LOCALE.country || "").toUpperCase();
    const bm = window.ItineroBrandMedia;
    const fork =
      (bm && typeof bm.forkForHome === "function" && bm.forkForHome(home, cc)) ||
      FORK_BY_CITY[home] ||
      (typeof FORK_FALLBACK === "function" ? FORK_FALLBACK(cc) : FORK_FALLBACK);
    if (!fork || !fork.a || !fork.b) {
      root.hidden = true;
      return;
    }
    root.hidden = false;
    const from = home || (cc === "US" ? "New York" : cc === "IN" ? "Mumbai" : "Home");
    const title = $("#fork-title");
    const sub = $("#fork-sub");
    const kicker = $("#fork-kicker");
    if (kicker) kicker.textContent = `Weekend hop · issued for ${from}`;
    if (title) title.textContent = `Two tickets out of ${from}`;
    if (sub) {
      sub.textContent = `${fork.a.city} or ${fork.b.city}. Punch a stub for stays, or ask Vero which hop fits.`;
    }
    paintForkPath($("#fork-a"), fork.a, from);
    paintForkPath($("#fork-b"), fork.b, from);

    const ask = $("#fork-ask-vero");
    if (ask) {
      ask.onclick = () => {
        const prompt = `From ${from}, help me choose between ${fork.a.city} and ${fork.b.city} this weekend: travel time, stay area, and which trip fits a calmer vs fuller pace.`;
        openVeroWith(prompt);
      };
    }

    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (!reduceMotion && "IntersectionObserver" in window) {
      const io = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              root.classList.add("is-in");
              io.disconnect();
            }
          });
        },
        { threshold: 0.28 }
      );
      io.observe(root);
    } else {
      root.classList.add("is-in");
    }
  }

