  /** Compact budget label for chips — INR keeps local “40k” feel; others use proper currency. */
  function formatBudgetChip(amount, currency) {
    const cur = String(currency || "USD").toUpperCase();
    const n = Math.round(Number(amount) || 0);
    if (!(n > 0)) return "";
    if (cur === "INR") {
      if (n >= 100000) return `₹${Math.round(n / 100000)}L`;
      if (n >= 1000) return `₹${Math.round(n / 1000)}k`;
      return `₹${n}`;
    }
    const loc = window.ItineroLocale;
    if (loc && typeof loc.money === "function") {
      const pretty = loc.money(n, cur);
      if (pretty) return pretty;
    }
    try {
      return new Intl.NumberFormat(cur === "GBP" ? "en-GB" : cur === "EUR" ? "en-IE" : "en-US", {
        style: "currency",
        currency: cur,
        maximumFractionDigits: 0,
      }).format(n);
    } catch (_) {
      return `${cur} ${n}`;
    }
  }

  function formatBudgetPhrase(amount, currency) {
    const label = formatBudgetChip(amount, currency);
    return label ? `under ${label}` : "mid budget";
  }

  /** USD anchors (~₹40k / ₹80k trip budgets) converted via ItineroLocale FX when available. */
  const INVITE_BUDGET_USD = { quiet: 480, beach: 960 };

  async function budgetInLocale(usdAmount) {
    const cur = localeCurrencyCode();
    const loc = window.ItineroLocale;
    if (cur === "USD") return usdAmount;
    if (loc && typeof loc.convertUsd === "function") {
      try {
        const converted = await loc.convertUsd(usdAmount, cur);
        if (converted > 0) {
          if (cur === "JPY" || cur === "KRW" || cur === "VND" || cur === "IDR") {
            return Math.round(converted / 1000) * 1000;
          }
          if (converted >= 1000) return Math.round(converted / 50) * 50;
          return Math.round(converted);
        }
      } catch (_) {}
    }
    /* Soft offline fallbacks when FX is cold */
    const approx = {
      INR: usdAmount * 83,
      EUR: usdAmount * 0.92,
      GBP: usdAmount * 0.79,
      AED: usdAmount * 3.67,
      SGD: usdAmount * 1.35,
      AUD: usdAmount * 1.52,
      CAD: usdAmount * 1.36,
      JPY: usdAmount * 150,
    };
    const n = approx[cur];
    if (!(n > 0)) return usdAmount;
    if (cur === "JPY") return Math.round(n / 1000) * 1000;
    if (n >= 1000) return Math.round(n / 50) * 50;
    return Math.round(n);
  }

