  function parseIso(iso) {
    if (!iso) return null;
    const d = new Date(`${iso}T12:00:00`);
    return Number.isNaN(d.getTime()) ? null : d;
  }

  /** Standard face format: 02 Nov 2026 */
  function formatFaceDate(iso) {
    const d = parseIso(iso);
    if (!d) return "Select date";
    const dd = String(d.getDate()).padStart(2, "0");
    const mon = d.toLocaleDateString("en-GB", { month: "short" });
    return `${dd} ${mon} ${d.getFullYear()}`;
  }

  /** Longer label inside the calendar */
  function formatCalTitle(iso) {
    const d = parseIso(iso);
    if (!d) return "Select a date";
    return d.toLocaleDateString("en-GB", {
      weekday: "short",
      day: "numeric",
      month: "long",
      year: "numeric",
    });
  }

  function toIso(d) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  }

  function filterAirports(q) {
    const s = String(q || "")
      .trim()
      .toLowerCase();
    if (!s) return AIRPORTS.slice(0, 8);
    return AIRPORTS.filter(
      (a) =>
        a.code.toLowerCase().includes(s) ||
        a.city.toLowerCase().includes(s) ||
        a.name.toLowerCase().includes(s)
    ).slice(0, 8);
  }

  function filterCities(q) {
    const s = String(q || "")
      .trim()
      .toLowerCase();
    if (!s) return CITIES.slice(0, 8);
    return CITIES.filter((c) => c.city.toLowerCase().includes(s) || c.meta.toLowerCase().includes(s)).slice(
      0,
      8
    );
  }

  function wireDockPickers() {
    const pop = $("#dock-pop");
    const dock = $("#search");
    if (!pop || !dock) return;

    let state = { kind: null, anchor: null, calMonth: null, activeIdx: 0, suggestReq: 0 };
    let suggestAbort = null;
    let lastSuggestPaint = [];

    function closePop() {
      pop.hidden = true;
      pop.innerHTML = "";
      pop.classList.remove("dock-pop--cal");
      $$("[aria-expanded='true']").forEach((el) => el.setAttribute("aria-expanded", "false"));
      state = { kind: null, anchor: null, calMonth: null, activeIdx: 0 };
    }

    function placePop(anchor) {
      const aRect = (anchor.closest?.(".cell") || anchor).getBoundingClientRect();
      const popW = Math.min(340, window.innerWidth - 24);
      let left = Math.max(12, Math.min(aRect.left, window.innerWidth - popW - 12));
      let top = aRect.bottom + 8;
      pop.style.width = `${popW}px`;
      pop.style.left = `${left}px`;
      pop.style.top = `${top}px`;
      requestAnimationFrame(() => {
        const pr = pop.getBoundingClientRect();
        if (pr.bottom > window.innerHeight - 12) {
          pop.style.top = `${Math.max(12, aRect.top - pr.height - 8)}px`;
        }
      });
    }

    function openPop(kind, anchor) {
      state.kind = kind;
      state.anchor = anchor;
      $$("[aria-expanded='true']").forEach((el) => {
        if (el !== anchor) el.setAttribute("aria-expanded", "false");
      });
      anchor.setAttribute("aria-expanded", "true");
      pop.classList.toggle("dock-pop--cal", kind === "calendar");
      pop.hidden = false;
      placePop(anchor.closest(".cell") || anchor);
    }

    function localSuggestRows(type, q, ds) {
      return type === "city"
        ? filterCities(q).map((c) => ({
            key: c.city,
            code: "",
            city: c.city,
            meta: c.meta,
            value: c.city,
          }))
        : ds && typeof ds.localAirportRows === "function"
          ? ds.localAirportRows(q, 8)
          : filterAirports(q).map((a) => ({
              key: a.code,
              code: a.code,
              city: a.city,
              meta: a.name,
              value: a.code,
            }));
    }

    function paintSuggestItems(input, items, paintOpts = {}) {
      state.activeIdx = 0;
      openPop("suggest", input);
      const qLen = String(input.value || "").trim().length;
      if (!items.length) {
        if (paintOpts.allowEmpty) {
          lastSuggestPaint = [];
          pop.innerHTML = `<p class="dock-pop__empty">No matches. Try a city or code.</p>`;
          return;
        }
        if (lastSuggestPaint.length) return;
        if (paintOpts.pending || qLen >= 2) {
          pop.innerHTML = `<p class="dock-pop__empty dock-pop__pending" role="status">Searching…</p>`;
          return;
        }
        return;
      }
      lastSuggestPaint = items;
      pop.innerHTML = `<ul class="dock-pop__list" role="listbox">${items
        .map(
          (it, i) => `
        <li>
          <button type="button" class="dock-pop__opt${i === 0 ? " is-active" : ""}" role="option" data-value="${escapeHtml(
            it.value
          )}" data-idx="${i}">
            <span class="dock-pop__copy">
              <span class="dock-pop__city">${escapeHtml(it.city)}</span>
              <span class="dock-pop__meta">${escapeHtml(it.meta)}</span>
            </span>
            ${it.code ? `<span class="dock-pop__code">${escapeHtml(it.code)}</span>` : ""}
          </button>
        </li>`
        )
        .join("")}</ul>`;

      $$(".dock-pop__opt", pop).forEach((btn) => {
        btn.addEventListener("mousedown", (e) => e.preventDefault());
        btn.addEventListener("click", () => {
          input.value = btn.dataset.value;
          closePop();
          input.focus();
        });
      });
    }

    function paintSuggestInstant(input) {
      const type = input.dataset.suggest;
      const q = String(input.value || "").trim();
      const ds = window.ItineroDestinationSuggest;
      const local = localSuggestRows(type, q, ds);
      if (local.length) {
        paintSuggestItems(input, local);
        return;
      }
      if (q.length >= 1 && !local.length) {
        paintSuggestItems(input, [], { pending: true });
      } else if (q.length === 0) {
        paintSuggestItems(input, local);
      }
    }

    function enrichSuggest(input) {
      const type = input.dataset.suggest;
      const q = String(input.value || "").trim();
      const qAtStart = q;
      const ds = window.ItineroDestinationSuggest;
      const local = localSuggestRows(type, q, ds);

      if (q.length < 2 || !ds) return;

      if (suggestAbort) suggestAbort.abort();
      suggestAbort = new AbortController();
      const apiSignal = suggestAbort.signal;

      const req = ++state.suggestReq;
      const finish = (items, settled) => {
        if (req !== state.suggestReq || state.anchor !== input) return;
        if (String(input.value || "").trim() !== qAtStart) return;
        const rows = items && items.length ? items : local;
        if (rows.length) paintSuggestItems(input, rows);
        else if (settled) paintSuggestItems(input, [], { allowEmpty: true });
      };

      if (type === "city" && typeof ds.query === "function") {
        ds.query(q, {
          mode: "hotel",
          limit: 8,
          signal: apiSignal,
          onPartial: (rows) => {
            if (req !== state.suggestReq || state.anchor !== input) return;
            const items = (rows || []).map((row) => ({
              key: row.city || row.title,
              code: "",
              city: row.city || row.title,
              meta: row.sub || row.tag || "",
              value: row.city || row.title,
            }));
            const merged = ds.filterRows ? ds.filterRows(q, items) : items;
            if (merged.length) paintSuggestItems(input, merged);
          },
        })
          .then((payload) => {
            const items = (payload.rows || []).map((row) => ({
              key: row.city || row.title,
              code: "",
              city: row.city || row.title,
              meta: row.sub || row.tag || "",
              value: row.city || row.title,
            }));
            const merged = ds.filterRows ? ds.filterRows(q, items) : items;
            finish(merged.length ? merged : local, true);
          })
          .catch(() => finish(local, true));
        return;
      }

      if (type === "airport" && typeof ds.queryAirports === "function") {
        ds.queryAirports(q, { limit: 8, signal: apiSignal }).then((payload) => {
          if (payload && payload.aborted) return;
          const items =
            typeof ds.mergeAirportRows === "function"
              ? ds.mergeAirportRows(local, payload.rows || [], 8)
              : (payload.rows || []).length
                ? payload.rows
                : local;
          finish(items, true);
        }).catch(() => {});
      }
    }

    function renderSuggest(input) {
      paintSuggestInstant(input);
      enrichSuggest(input);
    }

    function calHiddenFor(key) {
      if (key === "depart") return $("#depart-date");
      if (key === "return") return $("#return-date");
      if (key === "depart2") return $("#depart2-date");
      if (key === "checkin") return $("#checkin-date");
      if (key === "checkout") return $("#checkout-date");
      if (key === "xp-start") return $("#xp-start-date");
      if (key === "xp-end") return $("#xp-end-date");
      return null;
    }

    function calLabelFor(key) {
      return (
        {
          depart: "Depart",
          return: "Return",
          depart2: "Flight 2 · Depart",
          checkin: "Check-in",
          checkout: "Check-out",
          "xp-start": "Check-in",
          "xp-end": "Check-out",
        }[key] || "Date"
      );
    }

    function applyDate(faceBtn, iso) {
      const key = faceBtn.dataset.cal;
      const hidden = calHiddenFor(key);
      if (hidden) hidden.value = iso;
      faceBtn.textContent = formatFaceDate(iso);
      if (key === "depart" && tripType === "round") {
        const retIn = $("#return-date");
        const retFace = $("#return-face");
        if (retIn && (!retIn.value || retIn.value < iso)) {
          const next = parseIso(iso);
          next.setDate(next.getDate() + 7);
          retIn.value = toIso(next);
          if (retFace) retFace.textContent = formatFaceDate(retIn.value);
        }
      }
      if (key === "checkin") {
        const cout = $("#checkout-date");
        const coutFace = $("#checkout-face");
        if (cout && (!cout.value || cout.value <= iso)) {
          const next = parseIso(iso);
          next.setDate(next.getDate() + 1);
          const nextIso = toIso(next);
          cout.value = nextIso;
          if (coutFace) coutFace.textContent = formatFaceDate(nextIso);
        }
      }
      if (key === "xp-start") {
        const xend = $("#xp-end-date");
        const xendFace = $("#xp-end-face");
        if (xend && (!xend.value || xend.value <= iso)) {
          const next = parseIso(iso);
          next.setDate(next.getDate() + 1);
          const nextIso = toIso(next);
          xend.value = nextIso;
          if (xendFace) xendFace.textContent = formatFaceDate(nextIso);
        }
      }
      closePop();
    }

    function renderCalendar(faceBtn) {
      const key = faceBtn.dataset.cal;
      const hidden = calHiddenFor(key);
      const selected = hidden?.value || "";
      let minIso = isoPlus(0);
      if (key === "return") minIso = $("#depart-date")?.value || isoPlus(0);
      if (key === "depart2") minIso = $("#depart-date")?.value || isoPlus(0);
      if (key === "checkout") minIso = $("#checkin-date")?.value || isoPlus(0);
      if (key === "xp-end") minIso = $("#xp-start-date")?.value || isoPlus(0);
      const label = calLabelFor(key);
      const base = state.calMonth
        ? new Date(state.calMonth.getFullYear(), state.calMonth.getMonth(), 1)
        : selected
          ? parseIso(selected)
          : new Date();
      state.calMonth = new Date(base.getFullYear(), base.getMonth(), 1);

      const y = state.calMonth.getFullYear();
      const m = state.calMonth.getMonth();
      const monthLabel = state.calMonth.toLocaleDateString("en-GB", { month: "long", year: "numeric" });
      // Monday-first (ISO week)
      const firstDow = (new Date(y, m, 1).getDay() + 6) % 7;
      const daysInMonth = new Date(y, m + 1, 0).getDate();
      const todayIso = isoPlus(0);
      const tomorrowIso = isoPlus(1);
      const weekend = (() => {
        const d = new Date();
        const day = d.getDay();
        const add = day === 6 ? 0 : day === 0 ? 6 : 6 - day;
        d.setDate(d.getDate() + add);
        return toIso(d);
      })();

      const prevDisabled = toIso(new Date(y, m, 0)) < minIso;

      openPop("calendar", faceBtn);
      window.ItineroCalendar.mount(pop, { value: selected, min: minIso, onPick: (iso) => applyDate(faceBtn, iso) });
      return;
      const cells = [];
      for (let i = 0; i < firstDow; i++) cells.push(`<span class="dock-pop__day-spacer"></span>`);
      for (let d = 1; d <= daysInMonth; d++) {
        const iso = `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
        const disabled = iso < minIso;
        const on = iso === selected;
        const today = iso === todayIso;
        cells.push(
          `<button type="button" class="dock-pop__day${on ? " is-on" : ""}${today ? " is-today" : ""}" data-iso="${iso}" aria-label="${formatCalTitle(
            iso
          )}" ${disabled ? "disabled" : ""}>${d}</button>`
        );
      }

      const quick = [
        { id: "today", label: "Today", iso: todayIso },
        { id: "tomorrow", label: "Tomorrow", iso: tomorrowIso },
        { id: "weekend", label: "Weekend", iso: weekend },
      ].filter((q) => q.iso >= minIso);

      pop.innerHTML = `
        <div class="dock-pop__cal">
          <div class="dock-pop__cal-top">
            <p class="dock-pop__title">${label}</p>
            <p class="dock-pop__picked">${formatCalTitle(selected || todayIso)}</p>
          </div>
          <div class="dock-pop__quick" role="group" aria-label="Quick dates">
            ${quick
              .map(
                (q) =>
                  `<button type="button" class="dock-pop__chip${selected === q.iso ? " is-on" : ""}" data-quick="${
                    q.iso
                  }">${q.label}</button>`
              )
              .join("")}
          </div>
          <div class="dock-pop__head dock-pop__head--cal">
            <button type="button" class="dock-pop__navbtn" data-nav="-1" aria-label="Previous month" ${
              prevDisabled ? "disabled" : ""
            }>‹</button>
            <p class="dock-pop__month">${monthLabel}</p>
            <button type="button" class="dock-pop__navbtn" data-nav="1" aria-label="Next month">›</button>
          </div>
          <div class="dock-pop__week" aria-hidden="true">
            <span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span><span>Su</span>
          </div>
          <div class="dock-pop__grid">${cells.join("")}</div>
        </div>`;

      $$("[data-nav]", pop).forEach((b) =>
        b.addEventListener("click", () => {
          state.calMonth = new Date(y, m + Number(b.dataset.nav), 1);
          renderCalendar(faceBtn);
        })
      );
      $$("[data-quick]", pop).forEach((b) =>
        b.addEventListener("click", () => applyDate(faceBtn, b.dataset.quick))
      );
      $$(".dock-pop__day[data-iso]", pop).forEach((b) =>
        b.addEventListener("click", () => applyDate(faceBtn, b.dataset.iso))
