    wireDockPickers();
    wireSearch();

    const top = $("#top");
    const onScroll = () => top?.classList.toggle("is-solid", window.scrollY > 48);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();

    const year = $("#footer-year");
    if (year) year.textContent = String(new Date().getFullYear());

    await bootLocale();
    wireCurrency();
    await bootBrandMedia();

    renderBrowse();
    scrubSeededRecent();
    renderRecent();
    wireRecent();
    wireStartPaths();
    wireInvite();
    wireChrome();
    wireAuthChrome();
    // Final auth paint after chrome + app listeners are ready (Notifications CTA too).
    Promise.resolve(window.ItineroChrome?.hydrateAuth?.())
      .then((session) => {
        window.ItineroChrome?.wireChrome?.();
        paintAuthChrome(session || readSession());
      })
      .catch(() => paintAuthChrome(readSession()));
