  /** Never leave shelf media blank: error OR hung load → Unsplash. */
  function guardShelfImg(img, destId, size) {
    if (!img) return;
    const w = (size && size.w) || 700;
    const q = (size && size.q) || 75;
    const media = img.closest(".hcard__media, .route-lead__media, .route-lane__media");
    const swapUnsplash = () => {
      const bm = window.ItineroBrandMedia;
      if (img.dataset.unsplashFallback !== "1" && bm && typeof bm.unsplashFallback === "function") {
        img.dataset.unsplashFallback = "1";
        img.src = bm.unsplashFallback(destId || "", { w, q });
        return true;
      }
      img.removeAttribute("src");
      img.classList.add("is-broken");
      if (media) media.classList.add("is-fallback");
      return false;
    };
    const done = () => {
      if (img.dataset.imgGuardDone === "1") return;
      img.dataset.imgGuardDone = "1";
      if (timer) clearTimeout(timer);
    };
    img.addEventListener("load", () => {
      if (img.naturalWidth > 0) done();
      else swapUnsplash();
    });
    img.addEventListener("error", () => {
      swapUnsplash();
    });
    /* Supplier CDNs (cupid.travel etc.) often hang with no error — blank forever without this. */
    const timer = setTimeout(() => {
      if (img.dataset.imgGuardDone === "1") return;
      if (img.complete && img.naturalWidth > 0) {
        done();
        return;
      }
      swapUnsplash();
    }, 2800);
    if (img.complete) {
      if (img.naturalWidth > 0) done();
      else if (img.naturalWidth === 0) swapUnsplash();
    }
  }

  function paintStayRail(rail, list, prefix, opts = {}) {
    if (!rail) return;
    const rows = Array.isArray(list) ? list : [];
    if (!rows.length) {
      const msg = opts.empty || "Live stays will show here when inventory answers.";
      rail.innerHTML = `<p class="rail__empty">${escapeHtml(msg)}</p>`;
      return;
    }
    rail.innerHTML = rows.map((h, i) => stayHtml(h, i, prefix)).join("");
    rail.querySelectorAll("img").forEach((img) => {
      const btn = img.closest("[data-stay]");
      const idx = btn ? +String(btn.dataset.stay || "").replace(prefix, "") : -1;
      const row = idx >= 0 ? rows[idx] : null;
      const destId = (row && (row.destination || row.search)) || "";
      guardShelfImg(img, destId, { w: 700, q: 75 });
    });
    rail.querySelectorAll("[data-stay]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const i = +String(btn.dataset.stay).replace(prefix, "");
        if (rows[i]) applyHotel(rows[i]);
      });
    });
  }

