  function renderBrowse() {
    const home = guessHomeCity();
    const forkKey = forkHomeKey();
    const cc = String(HOME_LOCALE.country || "").toUpperCase();
    const curatedNear =
      NEAR_BY_CITY[forkKey] ||
      (cc === "IN" ? NEAR_BY_CITY.Mumbai : null) ||
      (cc === "US" ? NEAR_BY_CITY["New York"] : null) ||
      [];
    const nearTitle = $("#near-title");
    const nearSub = $("#near-sub");
    const cur =
      (window.ItineroLocale && window.ItineroLocale.currency && window.ItineroLocale.currency()) ||
      HOME_LOCALE.currency ||
      "USD";
    const nearLabel = home || (cc === "US" ? "you" : cc === "IN" ? "Mumbai" : "you");
    if (nearTitle) nearTitle.textContent = `Stays near ${nearLabel}`;
    if (nearSub) {
      nearSub.textContent = HOME_LOCALE.lat != null
        ? `Live hotels near you · prices in ${cur}`
        : home
          ? `Hotels around ${home} · prices in ${cur}`
          : `Live hotels near your location · prices in ${cur}`;
    }

    const routesSub = $("#routes-sub");
    const routesTitle = $("#routes-title");
    if (routesTitle) routesTitle.textContent = "Routes worth flying";
    if (routesSub) {
      const ap = HOME_LOCALE.airport ? ` from ${HOME_LOCALE.airport}` : "";
      routesSub.textContent = `Ideas${ap}. Live fares open next. We never invent prices here.`;
    }

    paintFlightRoutes();
    wireForkBand(forkKey);

    const nearRail = $("#near-rail");
    const worldRail = $("#world-rail");
    paintStayRail(nearRail, curatedNear, "n");
    paintStayRail(worldRail, WORLD_STAYS, "w");

    const bm = window.ItineroBrandMedia;
    if (!bm) return;

    if (typeof bm.fetchNearbyHotels === "function") {
      paintRailLoading(nearRail, Math.max(curatedNear.length, 3));
      bm
        .fetchNearbyHotels({
          city: home,
          lat: HOME_LOCALE.lat,
          lng: HOME_LOCALE.lng,
          limit: 4,
        })
        .then((liveNear) => {
          if (liveNear && liveNear.length) {
            paintStayRail(nearRail, liveNear, "n");
            return;
          }
          if (typeof bm.enrichStayList === "function") {
            return bm.enrichStayList(curatedNear, 2).then((rows) => {
              paintStayRail(
                nearRail,
                rows && rows.length ? rows : curatedNear,
                "n",
                { empty: `No live hotels near ${home} right now. Try Hotels search.` }
              );
            });
          }
          paintStayRail(nearRail, curatedNear, "n");
        })
        .catch(() => {
          paintStayRail(nearRail, curatedNear, "n", {
            empty: `Nearby hotels unavailable. Open Hotels to search ${home}.`,
          });
        });
    } else if (typeof bm.enrichStayList === "function") {
      bm.enrichStayList(curatedNear, 2).then((rows) => {
        if (rows && rows.length) paintStayRail(nearRail, rows, "n");
      });
    }

    if (typeof bm.enrichStayList === "function") {
      bm.enrichStayList(WORLD_STAYS, 2).then((liveWorld) => {
        if (!liveWorld || !liveWorld.length) return;
        WORLD_STAYS = liveWorld;
        paintStayRail(worldRail, WORLD_STAYS, "w");
      });
    }
  }

