/**
 * Homepage brand media — destination-keyed catalog + optional LiteAPI hotel photos.
 * Source of truth: /homepage/brand-media.json
 */
(function (root) {
  "use strict";

  var CATALOG_URL = "/homepage/brand-media.json?v=6";
  var catalog = null;
  var heroTimer = 0;
  var heroIdx = 0;
  /** Unsplash photo ids claimed this homepage pass (hero first, then shelves). */
  var claimedPhotos = Object.create(null);
  /** Last-resort travel photo — homepage must never paint blank media. */
  var DEFAULT_UNSPLASH =
    "https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w={w}&q={q}";

  function localeCurrency() {
    if (root.ItineroLocale && typeof root.ItineroLocale.currency === "function") {
      return root.ItineroLocale.currency() || "USD";
    }
    try {
      var raw = localStorage.getItem("itinero_currency") || "";
      if (/^[A-Z]{3}$/.test(raw)) return raw;
    } catch (_) {}
    return "USD";
  }

  function localeSnapshot() {
    if (root.ItineroLocale && typeof root.ItineroLocale.get === "function") {
      return root.ItineroLocale.get() || {};
    }
    return {};
  }

  function moneyFmt(amount, currency) {
    var cur = String(currency || localeCurrency() || "USD").toUpperCase();
    if (root.ItineroLocale && typeof root.ItineroLocale.money === "function") {
      var pretty = root.ItineroLocale.money(amount, cur);
      if (pretty) return pretty;
    }
    return formatPrice(amount, cur);
  }

  function daySeed() {
    var d = new Date();
    return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000);
  }

  function hash(str) {
    var h = 0;
    var s = String(str || "");
    for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return h;
  }

  function sizeUrl(tpl, w, q) {
    if (!tpl) return "";
    return String(tpl)
      .replace(/\{w\}/g, String(w || 1600))
      .replace(/\{q\}/g, String(q || 75));
  }

  /**
   * Always return a paint-able Unsplash URL for a destination (or global default).
   * Used when LiteAPI / remote thumbs fail so shelves never go blank.
   */
  function unsplashFallback(destinationId, opts) {
    opts = opts || {};
    var w = opts.w || opts.cardW || 900;
    var q = opts.q || opts.cardQ || 75;
    var d = dest(destinationId);
    if (d) {
      var heroes = Array.isArray(d.heroes) ? d.heroes.filter(Boolean) : [];
      for (var i = 0; i < heroes.length; i++) {
        var url = sizeUrl(heroes[i], w, q);
        if (url) return url;
      }
    }
    return sizeUrl(DEFAULT_UNSPLASH, w, q);
  }

  function dest(id) {
    if (!catalog || !catalog.destinations) return null;
    return catalog.destinations[id] || null;
  }

  function photoKey(tpl) {
    var m = String(tpl || "").match(/\/(photo-[a-zA-Z0-9_-]+)/);
    return m ? m[1] : String(tpl || "");
  }

  function resetPhotoClaims() {
