(function (root) {
  const SESSION_KEY = "itinero_proto_session_v1";
  const TOKEN_KEY = "itinero_auth_token";
  const DEVICE_KEY = "itinero_device_id";
  const CONFIG_KEY = "itinero_auth_config_v1";
  const AUTH_REV_KEY = "itinero_auth_rev";

  let authConfig = null;

  const $ = (s, r = document) => r.querySelector(s);

  function readToken() {
    try {
      return localStorage.getItem(TOKEN_KEY) || "";
    } catch (_) {
      return "";
    }
  }

  function normalizeEmail(raw) {
    return String(raw || "").trim().toLowerCase();
  }

  function readSession() {
    try {
      const s = JSON.parse(localStorage.getItem(SESSION_KEY) || "null");
      if (!s || typeof s !== "object") return null;
      if (s.email || s.phone || s.id) return s;
      return null;
    } catch (_) {
      return null;
    }
  }

  function loadCachedAuthConfig() {
    try {
      return JSON.parse(localStorage.getItem(CONFIG_KEY) || "null");
    } catch (_) {
      return null;
    }
  }

  function useCookieAuth() {
    const c = authConfig || loadCachedAuthConfig();
    return Boolean(c && c.cookieAuth);
  }

  function useLocalToken() {
    const c = authConfig || loadCachedAuthConfig();
    if (!c) return true;
    return c.localToken !== false;
  }

  async function fetchAuthConfig() {
    try {
      const res = await fetch("/api/v1/auth/config", {
        credentials: "include",
        headers: { Accept: "application/json" },
      });
      const data = await res.json().catch(() => ({}));
      if (data && data.ok !== false) {
        authConfig = data;
        localStorage.setItem(CONFIG_KEY, JSON.stringify(data));
      }
    } catch (_) {}
    return authConfig;
  }

  function authFetchOpts(extra) {
    return { credentials: useCookieAuth() ? "include" : "same-origin", ...(extra || {}) };
  }

  function bumpAuthRev() {
    try {
      localStorage.setItem(AUTH_REV_KEY, String(Date.now()));
    } catch (_) {}
  }

  function saveSession(session, token) {
    try {
      if (session && (session.email || session.phone || session.id)) {
        localStorage.setItem(SESSION_KEY, JSON.stringify(session));
      }
      if (token && useLocalToken()) {
        localStorage.setItem(TOKEN_KEY, token);
      } else if (token && !useLocalToken()) {
        localStorage.removeItem(TOKEN_KEY);
      }
    } catch (_) {}
  }

  function sessionEmail() {
    const s = readSession();
    return s?.email ? normalizeEmail(s.email) : "";
  }

  function sessionPhone() {
    const s = readSession();
    return String(s?.phone || s?.mobileNumber || "").trim();
  }

  function deviceId() {
    try {
      let id = localStorage.getItem(DEVICE_KEY);
      if (!id) {
        id = "dev_" + Math.random().toString(36).slice(2, 12);
        localStorage.setItem(DEVICE_KEY, id);
      }
      return id;
    } catch (_) {
      return "dev_anon";
    }
  }

  function authHeaders(json) {
    const h = { Accept: "application/json" };
    if (json) h["Content-Type"] = "application/json";
    h["X-Itinero-Device"] = deviceId();
    if (!useCookieAuth()) {
      const t = readToken();
      if (t) h.Authorization = "Bearer " + t;
    }
    return h;
  }

  function initials(session) {
    if (session?.name) return session.name.trim().charAt(0).toUpperCase();
    const hint = session?.email || session?.phone || "A";
    return String(hint).charAt(0).toUpperCase();
  }

  function clearAuthLocal() {
    try {
      localStorage.removeItem(SESSION_KEY);
      localStorage.removeItem(TOKEN_KEY);
      bumpAuthRev();
    } catch (_) {}
  }

  async function hydrateAuth() {
    if (!authConfig) {
      try {
        await fetchAuthConfig();
      } catch (_) {}
    }
    // Cookie-only prod: try profile whenever cookie auth is on (or a bearer token exists).
    if (!useCookieAuth() && !readToken()) return readSession();
    try {
      const res = await fetch("/api/v1/auth/profile", {
        ...authFetchOpts(),
        headers: authHeaders(),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        if (res.status === 401) clearAuthLocal();
        return null;
      }
      const user = data.user || {};
      const session = {
        email: user.email || "",
        phone: user.phone || user.mobileNumber || "",
        name: user.name || user.displayName || "",
        id: user.id || "",
        at: Date.now(),
        needs_setup: Boolean(user.needs_setup),
        missingContacts: Array.isArray(user.missingContacts) ? user.missingContacts : [],
      };
      const tok = useLocalToken() ? readToken() : "";
      saveSession(session, tok || null);
      return session;
    } catch (_) {
      return readSession();
    }
  }

  async function signOut() {
    try {
      await fetch("/api/v1/auth/logout", {
        method: "POST",
        ...authFetchOpts(),
        headers: authHeaders(true),
      });
    } catch (_) {}
    clearAuthLocal();
    location.href = "/homepage/";
  }

  function wireMobileNav() {
    const tools = $(".top__tools");
    const nav = $(".top__nav");
    if (!tools || !nav) return;
    if ($("#menu-btn") || $("#site-drawer") || $("#top-menu")) return;

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "top__menu";
    btn.id = "top-menu";
    btn.setAttribute("aria-expanded", "false");
    btn.setAttribute("aria-controls", "chrome-drawer");
    btn.setAttribute("aria-label", "Open menu");
    btn.innerHTML =
      '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"><path d="M4 7h16M4 12h16M4 17h16"/></svg>';

    const drawer = document.createElement("div");
    drawer.className = "chrome-drawer";
    drawer.id = "chrome-drawer";
    drawer.hidden = true;
