            <p class="footer__col-title">Help</p>
            <a class="footer__col-link" href="/help"${currentAttr("/help")}>Support</a>
            <a class="footer__col-link" href="/terms"${currentAttr("/terms")}>Terms</a>
            <a class="footer__col-link" href="/privacy"${currentAttr("/privacy")}>Privacy</a>
            <a class="footer__col-link" href="/cancellation"${currentAttr("/cancellation")}>Cancellations</a>
          </nav>
        </div>
        <div class="footer__aside">
          <form class="footer__subscribe" id="proto-newsletter" novalidate>
            <p class="footer__subscribeLabel" id="footer-newsletter-label">Trip ideas in your inbox</p>
            <div class="footer__subscribeRow">
              <label class="sr-only" for="footer-newsletter">Email</label>
              <input id="footer-newsletter" type="email" required placeholder="you@email.com" autocomplete="email" aria-labelledby="footer-newsletter-label" />
              <button type="submit">Join</button>
            </div>
            <p class="footer__subscribeStatus" id="footer-newsletter-status" hidden></p>
          </form>
          <a class="footer__ig" href="https://www.instagram.com/itinero/" rel="noopener noreferrer" target="_blank">
            <span class="footer__ig-icon" aria-hidden="true">
              <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7">
                <rect x="3" y="3" width="18" height="18" rx="5" />
                <circle cx="12" cy="12" r="4" />
                <circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none" />
              </svg>
            </span>
            <span class="footer__ig-text">
              <span class="footer__ig-label">Instagram</span>
              <span class="footer__ig-handle">@itinero</span>
            </span>
          </a>
        </div>
      </div>
      <div class="footer__bar">
        <p class="footer__copy">© <span id="footer-year"></span> Itinero Travels Private Limited</p>
        <p class="footer__bar-note">Flights · stays · plans that feel like you</p>
      </div>
    </div>`;
  }

  function upgradeSiteFooter() {
    const footer = document.querySelector("footer.footer");
    if (!footer || document.body.classList.contains("vero-body")) return;
    if (footer.getAttribute("data-chrome-footer") === "1") return;
    footer.setAttribute("data-chrome-footer", "1");
    footer.innerHTML = siteFooterHtml();
    if (!document.querySelector('script[src*="site-footer-newsletter"]')) {
      const s = document.createElement("script");
      s.src = "/site-footer-newsletter-30.js?v=20261016footer1";
      s.defer = true;
      document.body.appendChild(s);
    }
  }

  function wireGlassTop() {
    const top = $("#top");
    if (!top) return;
    const glass =
      document.body.classList.contains("xp-standalone") ||
      document.body.classList.contains("cat-page") ||
      (document.body.classList.contains("xp-page") &&
        !document.body.classList.contains("xp-page--results") &&
        !document.body.classList.contains("hx-page--detail") &&
        !document.body.classList.contains("hx-page--booking")) ||
      document.documentElement.getAttribute("data-flights-mode") === "explore";
    if (!glass) return;
    const onScroll = () => top.classList.toggle("is-solid", window.scrollY > 48);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();
  }

  function wireChrome() {
    upgradeSiteFooter();
    const year = $("#footer-year");
    if (year) year.textContent = String(new Date().getFullYear());
    wireGlassTop();
    wireMobileNav();
    const themeMenu = $("#account-menu");
    if (themeMenu && !themeMenu.querySelector("[data-theme-toggle]")) {
      const item = document.createElement("button");
      item.type = "button";
      item.setAttribute("role", "menuitem");
      item.setAttribute("data-theme-toggle", "");
      const before = $("#signout-btn");
      if (before) themeMenu.insertBefore(item, before);
      else themeMenu.appendChild(item);
    }
    if (root.ItineroTheme) {
      document.querySelectorAll("[data-theme-toggle]").forEach((el) => {
        if (typeof root.ItineroTheme.bind === "function") root.ItineroTheme.bind(el);
      });
      if (typeof root.ItineroTheme.sync === "function") root.ItineroTheme.sync();
    }

    const session = readSession();
    const signin = $("#top-signin");
    const account = $("#top-account");

    // Notifications sheet must track cookie session (never leave "Sign in for live alerts"
    // up while the account pill already shows a signed-in name).
    const alertsCopy = $("#alerts-empty-copy") || $("#alerts-empty")?.querySelector(".sheet__empty-copy");
    const alertsCta = $("#alerts-cta") || $("#alerts-panel")?.querySelector("a.sheet__link");
    if (session) {
      if (alertsCopy) {
        alertsCopy.textContent =
          "Price watches and trip drafts show up here when you save them. We never invent placeholders.";
      }
      if (alertsCta) {
        alertsCta.hidden = false;
        alertsCta.textContent = "Manage account";
        alertsCta.setAttribute("href", "/account/");
      }
    } else {
      if (alertsCopy) {
        alertsCopy.textContent =
          "After you sign in, price watches and trip drafts show up here. We never use invented placeholders.";
      }
      if (alertsCta) {
        alertsCta.hidden = false;
        alertsCta.textContent = "Sign in for live alerts";
        alertsCta.setAttribute("href", "/homepage/signin.html");
      }
    }

    if (!session) {
      if (signin) signin.hidden = false;
      if (account) account.hidden = true;
      return;
    }
    if (signin) signin.hidden = true;
    if (account) account.hidden = false;
    const avatar = $("#account-avatar");
    const label = $("#account-label");
    const email = $("#account-email");
    if (avatar) avatar.textContent = initials(session);
    if (label) label.textContent = session.name || "Account";
    if (email) email.textContent = session.email || session.phone || "";

    // Keep Manage account / Account menu links on /account/ (never bounce to sign-in).
    account?.querySelectorAll('a[role="menuitem"]').forEach((a) => {
      const href = a.getAttribute("href") || "";
      if (/signin\.html/i.test(href) && /manage|account/i.test(a.textContent || "")) {
        a.setAttribute("href", "/account/");
      }
    });

    const btn = $("#account-btn");
    const menu = $("#account-menu");
    if (btn && menu && !btn.dataset.chromeAccountWired) {
      btn.dataset.chromeAccountWired = "1";
      const close = () => {
        menu.hidden = true;
        btn.setAttribute("aria-expanded", "false");
      };
      let ignoreDoc = false;
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
        ignoreDoc = true;
        const open = menu.hidden;
        menu.hidden = !open;
        btn.setAttribute("aria-expanded", open ? "true" : "false");
        setTimeout(() => {
          ignoreDoc = false;
        }, 0);
      });
      document.addEventListener("click", (e) => {
        if (ignoreDoc || account?.contains(e.target)) return;
        close();
      });
      document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") close();
      });
      const signoutBtn = $("#signout-btn");
      if (signoutBtn && !signoutBtn.dataset.chromeAccountWired) {
        signoutBtn.dataset.chromeAccountWired = "1";
        signoutBtn.addEventListener("click", signOut);
      }
    }
  }

  function toast(msg) {
    let el = $("#toast");
    if (!el) {
      el = document.createElement("div");
      el.className = "toast";
      el.id = "toast";
      el.hidden = true;
      el.setAttribute("role", "status");
      document.body.appendChild(el);
    }
    el.textContent = msg;
    el.hidden = false;
    clearTimeout(toast._t);
    toast._t = setTimeout(() => {
      el.hidden = true;
    }, 2200);
  }

  root.ItineroChrome = {
    readSession,
    readToken,
    saveSession,
    sessionEmail,
    sessionPhone,
    normalizeEmail,
    deviceId,
    authHeaders,
    hydrateAuth,
    fetchAuthConfig,
    useCookieAuth,
    useLocalToken,
    authFetchOpts,
    wireChrome,
    signOut,
    clearAuthLocal,
    toast,
  };

  function bootChrome() {
    // Hydrate cookie/token session BEFORE first paint so signed-in users never
    // flash the Sign in CTA (then flip to the account pill).
    fetchAuthConfig()
      .then(async () => {
        if (useCookieAuth() || readToken()) {
          await hydrateAuth();
        }
        wireChrome();
      })
      .catch(() => {
        wireChrome();
      });
  }

  window.addEventListener("storage", (e) => {
    if (e.key === AUTH_REV_KEY || e.key === SESSION_KEY || e.key === TOKEN_KEY) {
      wireChrome();
      if (e.key === AUTH_REV_KEY && e.newValue) hydrateAuth().then(() => wireChrome());
    }
  });

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", bootChrome);
  else bootChrome();
})(window);

