/**
 * Shared destination / airport autocomplete for hotels, experiences, and homepage.
 * Cities: local seed → geo + places (+ optional Typesense when live).
 * Airports: local/IATA seed first → GET /api/flights/airports (Typesense skipped when dead).
 */
(function (root) {
  "use strict";

  var DEBOUNCE_MS = 80;
  var TIMEOUT_MS = 4500;
  var AIRPORT_TIMEOUT_MS = 2800;
  var CACHE_MAX = 64;

  var queryCache = Object.create(null);
  var airportInflight = null;

  var DESTINATIONS = [
    { title: "Paris", sub: "France", lat: 48.8566, lng: 2.3522 },
    { title: "Tokyo", sub: "Japan", lat: 35.6762, lng: 139.6503 },
    { title: "Dubai", sub: "United Arab Emirates", lat: 25.2048, lng: 55.2708 },
    { title: "Bali", sub: "Indonesia", lat: -8.4095, lng: 115.1889 },
    { title: "New York", sub: "United States", lat: 40.7128, lng: -74.006 },
    { title: "London", sub: "United Kingdom", lat: 51.5074, lng: -0.1278 },
    { title: "Rome", sub: "Italy", lat: 41.9028, lng: 12.4964 },
    { title: "Mumbai", sub: "India", lat: 19.076, lng: 72.8777 },
    { title: "New Delhi", sub: "India", lat: 28.6139, lng: 77.209 },
    { title: "Bengaluru", sub: "India", lat: 12.9716, lng: 77.5946 },
    { title: "Goa", sub: "India", lat: 15.2993, lng: 74.124 },
    { title: "Jaipur", sub: "India", lat: 26.9124, lng: 75.7873 },
    { title: "Singapore", sub: "Singapore", lat: 1.3521, lng: 103.8198 },
    { title: "Bangkok", sub: "Thailand", lat: 13.7563, lng: 100.5018 },
    { title: "Hong Kong", sub: "Hong Kong", lat: 22.3193, lng: 114.1694 },
    { title: "Istanbul", sub: "Türkiye", lat: 41.0082, lng: 28.9784 },
    { title: "Barcelona", sub: "Spain", lat: 41.3874, lng: 2.1686 },
    { title: "Amsterdam", sub: "Netherlands", lat: 52.3676, lng: 4.9041 },
    { title: "Los Angeles", sub: "United States", lat: 34.0522, lng: -118.2437 },
    { title: "San Francisco", sub: "United States", lat: 37.7749, lng: -122.4194 },
    { title: "Sydney", sub: "Australia", lat: -33.8688, lng: 151.2093 },
    { title: "Cape Town", sub: "South Africa", lat: -33.9249, lng: 18.4241 },
    { title: "Kyoto", sub: "Japan", lat: 35.0116, lng: 135.7681 },
    { title: "Lisbon", sub: "Portugal", lat: 38.7223, lng: -9.1393 },
  ];

  var AIRPORTS = [
    { code: "JFK", city: "New York", name: "John F. Kennedy" },
    { code: "EWR", city: "Newark", name: "Newark Liberty" },
    { code: "LAX", city: "Los Angeles", name: "Los Angeles Intl" },
    { code: "SFO", city: "San Francisco", name: "San Francisco Intl" },
    { code: "ORD", city: "Chicago", name: "O'Hare" },
    { code: "BOM", city: "Mumbai", name: "Chhatrapati Shivaji" },
    { code: "DEL", city: "New Delhi", name: "Indira Gandhi" },
    { code: "BLR", city: "Bengaluru", name: "Kempegowda" },
    { code: "HYD", city: "Hyderabad", name: "Rajiv Gandhi" },
    { code: "MAA", city: "Chennai", name: "Chennai International" },
    { code: "CCU", city: "Kolkata", name: "Netaji Subhas Chandra Bose" },
    { code: "GOI", city: "Goa", name: "Dabolim" },
    { code: "PNQ", city: "Pune", name: "Pune International" },
    { code: "AMD", city: "Ahmedabad", name: "Sardar Vallabhbhai Patel" },
    { code: "STV", city: "Surat", name: "Surat Airport" },
    { code: "COK", city: "Kochi", name: "Cochin International" },
    { code: "JAI", city: "Jaipur", name: "Jaipur International" },
    { code: "DXB", city: "Dubai", name: "Dubai International" },
    { code: "SIN", city: "Singapore", name: "Changi" },
    { code: "BKK", city: "Bangkok", name: "Suvarnabhumi" },
    { code: "LHR", city: "London", name: "Heathrow" },
    { code: "CDG", city: "Paris", name: "Charles de Gaulle" },
    { code: "IST", city: "Istanbul", name: "Istanbul Airport" },
  ];

  function cacheGet(key) {
    return queryCache[key];
  }

  function cacheSet(key, val) {
    var keys = Object.keys(queryCache);
    if (keys.length >= CACHE_MAX) delete queryCache[keys[0]];
    queryCache[key] = val;
  }

  function primaryTerm(q) {
    return String(q || "")
      .split(",")[0]
      .trim()
      .toLowerCase()
      .replace(/[\u0300-\u036f]/g, "");
  }

  function isJunkRow(row, q) {
    var term = primaryTerm(q);
    var city = String(row.city || row.title || row.name || "")
      .toLowerCase()
      .replace(/[\u0300-\u036f]/g, "");
    var sub = String(row.sub || row.tag || row.address || row.state || "").toLowerCase();
    if (term === "goa") {
      if (city === "goa" && sub.indexOf("goa") === -1 && sub.indexOf("india") !== -1) return true;
      if (city.indexOf("goa") === 0 && city !== "goa" && (sub.indexOf("jammu") !== -1 || sub.indexOf("kashmir") !== -1)) return true;
    }
    // Jaipur typed → Chittagong / Assam noise (Muse Nov10).
    if (term === "jaipur" || term.indexOf("jaipur") === 0) {
      if (/chittagong|chattogram|bangladesh|assam|sylhet|dhaka/.test(sub) || /chittagong|assam/.test(city)) {
        return true;
      }
    }
    return false;
  }

  function rowMatchesQuery(row, q) {
    var term = primaryTerm(q);
    if (!term || term.length < 2) return true;
    var blob = [
      row.title,
      row.city,
      row.name,
      row.sub,
      row.tag,
      row.label,
      row.address,
      row.state,
    ]
      .join(" ")
      .toLowerCase()
      .replace(/[\u0300-\u036f]/g, "");
    if (blob.indexOf(term) !== -1) return true;
    // Allow short prefix matches on the primary city token.
    var city = String(row.city || row.title || "")
      .toLowerCase()
      .replace(/[\u0300-\u036f]/g, "");
    return city.indexOf(term) === 0;
  }

  function filterRows(q, rows) {
    return (rows || []).filter(function (r) {
      return r && (r.title || r.city) && !isJunkRow(r, q) && rowMatchesQuery(r, q);
    });
  }

  function localRows(q, limit) {
    var s = String(q || "").trim().toLowerCase();
    var lim = limit || 8;
    if (!s) return DESTINATIONS.slice(0, lim).map(toRow);
    return DESTINATIONS.filter(function (d) {
      return d.title.toLowerCase().indexOf(s) !== -1 || d.sub.toLowerCase().indexOf(s) !== -1;
    })
      .slice(0, lim)
      .map(toRow);
  }

  function localAirportRows(q, limit) {
    var s = String(q || "")
      .trim()
      .toLowerCase();
    var lim = limit || 8;
    if (!s) return AIRPORTS.slice(0, lim).map(airportToRow);
    return AIRPORTS.filter(function (a) {
      return (
        a.code.toLowerCase().indexOf(s) !== -1 ||
        a.city.toLowerCase().indexOf(s) !== -1 ||
        a.name.toLowerCase().indexOf(s) !== -1
      );
    })
      .slice(0, lim)
      .map(airportToRow);
  }

  function airportToRow(a) {
    return {
      key: a.code,
      code: a.code,
      city: a.city,
      meta: a.name,
      value: a.code,
      title: a.city,
      sub: a.name,
      label: a.city + " (" + a.code + ")",
    };
  }

  function mergeAirportRows(local, remote, limit) {
    var seen = {};
    var out = [];
    (local || []).concat(remote || []).forEach(function (row) {
      var code = String(row.code || row.value || "").toUpperCase();
      if (!code || seen[code]) return;
      seen[code] = 1;
      out.push(row);
    });
    return out.slice(0, limit || 8);
  }

  function toRow(d) {
    return {
      id: d.id || "",
      title: d.title,
      sub: d.sub || "",
      label: d.label || d.title,
      city: d.title,
      tag: d.sub || "",
      lat: d.lat != null ? d.lat : null,
      lng: d.lng != null ? d.lng : null,
    };
  }

  function mergeRows(q, chunks, limit) {
    var seen = {};
    var out = [];
    filterRows(
      q,
      [].concat.apply([], chunks).filter(Boolean)
    ).forEach(function (row) {
      var key = [
        String(row.title || row.city || "").toLowerCase(),
        row.lat != null ? Number(row.lat).toFixed(2) : "",
        row.lng != null ? Number(row.lng).toFixed(2) : "",
      ].join("|");
      if (!key.replace(/\|/g, "") || seen[key]) return;
      seen[key] = 1;
      out.push(row);
    });
    return out.slice(0, limit || 8);
  }

  function mapLocations(data) {
    var list = data && Array.isArray(data.suggestions) ? data.suggestions : [];
    return list.map(function (s) {
      var title = String(s.name || "").trim();
      var sub = String(s.subtitle || s.country_name || "").trim();
      var label = s.label || (sub && title ? title + ", " + sub : title);
      return {
        id: String(s.id || ""),
        title: title,
        sub: sub && sub !== title ? sub : "",
        label: label,
        city: s.city || title,
        tag: sub || s.category || "City",
        lat: s.latitude != null ? s.latitude : null,
        lng: s.longitude != null ? s.longitude : null,
      };
    });
  }

  function mapGeo(data) {
    var items = [];
    if (data && data.place) items.push(data.place);
    (data && data.items ? data.items : []).forEach(function (item) {
      items.push(item);
    });
    return items.map(function (p) {
      var title = String(p.name || p.city || "").trim();
      var sub = String(p.address || p.label || p.country || "").trim();
      return {
        id: "",
        title: title,
        sub: sub && sub !== title ? sub : "",
        label: p.label || sub || title,
        city: title,
        tag: sub || "Destination",
        lat: p.lat != null ? p.lat : p.latitude,
        lng: p.lng != null ? p.lng : p.longitude,
        state: p.state || "",
      };
    });
  }

  function mapPlaces(data) {
    var list = data && Array.isArray(data.places) ? data.places : [];
    return list.map(function (p) {
      var title = String(p.name || "").trim();
      var sub = String(p.subtitle || p.address || "").trim();
      var label =
        sub && title && sub.toLowerCase().indexOf(title.toLowerCase()) === -1 ? title + ", " + sub : title || sub;
      return {
        id: String(p.id || ""),
        title: title || label,
        sub: sub && sub !== title ? sub : "",
        label: label || title,
        city: title || label,
        tag: sub || "Place",
        lat: p.lat != null ? p.lat : p.latitude,
        lng: p.lng != null ? p.lng : p.longitude,
      };
    });
  }

  function mapFlightsAirports(data) {
    var list =
      data && Array.isArray(data.airports)
        ? data.airports
        : data && Array.isArray(data.choices)
          ? data.choices
          : [];
    return list
      .map(function (a) {
        var code = String(a.code || a.iata || a.id || "").toUpperCase();
        if (!/^[A-Z]{3}$/.test(code)) return null;
        var city = String(a.city || a.city_name || a.name || code).trim();
        var name = String(a.name || a.label || "").trim();
        return {
          key: code,
          code: code,
          city: city,
          meta: name || city,
          value: code,
          title: city,
          sub: name,
          label: city + " (" + code + ")",
        };
      })
      .filter(Boolean);
  }

  function fetchJson(path, signal) {
    return fetch(path, {
      credentials: "same-origin",
      headers: { Accept: "application/json" },
      signal: signal,
    })
      .then(function (res) {
        if (!res.ok) return null;
        return res.json().catch(function () {
          return null;
        });
      })
      .catch(function (err) {
        if (err && err.name === "AbortError") throw err;
        return null;
      });
  }

  function abortAirportInflight() {
    if (airportInflight) {
      try {
        airportInflight.abort();
      } catch (_) {}
      airportInflight = null;
    }
  }

  /**
   * @param {string} q
   * @param {{ mode?: 'hotel'|'flight'|'destination', limit?: number, signal?: AbortSignal }} opts
   */
  function query(q, opts) {
    opts = opts || {};
    var queryText = String(q || "").trim();
    var limit = opts.limit || 8;
    var mode = opts.mode || "destination";
    if (queryText.length < 2) {
      return Promise.resolve({ rows: localRows(queryText, limit), degraded: false });
    }

    var cacheKey = "dest:" + mode + ":" + queryText.toLowerCase() + ":" + limit;
    var cached = cacheGet(cacheKey);
    if (cached) {
      return Promise.resolve({ rows: cached, degraded: false, cached: true });
    }

    var local = localRows(queryText, limit);
    var controller = opts.signal ? null : new AbortController();
    var signal = opts.signal || (controller && controller.signal);
    var timer =
      controller &&
      setTimeout(function () {
        try {
          controller.abort();
        } catch (_) {}
      }, TIMEOUT_MS);

    var enc = encodeURIComponent(queryText);
    var onPartial = typeof opts.onPartial === "function" ? opts.onPartial : null;
    var partsAcc = [];
    var tasks = [
      fetchJson("/api/geo/search?q=" + enc + "&limit=" + limit, signal).then(function (data) {
        var rows = mapGeo(data || {});
        partsAcc[0] = rows;
        if (onPartial && rows.length) {
          var early = mergeRows(queryText, partsAcc.filter(Boolean), limit);
          if (early.length) onPartial(early);
        }
        return rows;
      }),
      fetchJson("/api/places/suggest?q=" + enc + "&limit=" + limit, signal).then(function (data) {
        var rows = mapPlaces(data || {});
        partsAcc[1] = rows;
        if (onPartial && rows.length) {
          var early = mergeRows(queryText, partsAcc.filter(Boolean), limit);
          if (early.length) onPartial(early);
        }
        return rows;
      }),
    ];
    if (mode !== "flight") {
      var locMode = mode === "hotel" ? "hotel" : "all";
      tasks.push(
        fetchJson("/api/locations/suggest?q=" + enc + "&mode=" + locMode + "&limit=" + limit, signal).then(function (data) {
          var rows = mapLocations(data || {});
          partsAcc[2] = rows;
          if (onPartial && rows.length) {
