    let mount = host;
    let initial = (opts && opts.currency) || currency();

    if (host.tagName === "SELECT") {
      initial = validCurrency(host.value) || initial;
      const wrap = document.createElement("div");
      wrap.className = "top__currency currency-ctl";
      wrap.id = host.id || "currency-ctl";
      if (host.parentElement) {
        host.parentElement.replaceChild(wrap, host);
      }
      mount = wrap;
    } else {
      mount.classList.add("currency-ctl");
      if (!mount.classList.contains("top__currency")) mount.classList.add("top__currency");
      mount.innerHTML = "";
    }
    if (typeof (opts && opts.onChange) === "function") mount._currencyOnChange = opts.onChange;

    const menuId = (mount.id || "currency-ctl") + "-menu";
    mount.dataset.currencyCtl = "1";
    mount.innerHTML =
      `<button type="button" class="currency-ctl__btn" aria-haspopup="listbox" aria-expanded="false" aria-controls="${menuId}">` +
      `<span class="currency-ctl__label"></span>${CHEVRON}</button>` +
      `<ul class="currency-ctl__menu" id="${menuId}" role="listbox" aria-label="Currencies" hidden></ul>`;

    paintTrigger(mount, initial);

    const btn = mount.querySelector(".currency-ctl__btn");
    const menu = mount.querySelector(".currency-ctl__menu");

    function pick(code, { close } = { close: true }) {
      const next = setCurrency(code, { lock: true });
      paintTrigger(mount, next.currency || code);
      if (close) {
        closeMenu(mount);
        btn.focus();
      } else {
        menu.innerHTML = buildMenuItems(next.currency || code);
      }
      if (typeof mount._currencyOnChange === "function") mount._currencyOnChange(next.currency || code, next);
    }

    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (menu.hidden) openMenu(mount);
      else closeMenu(mount);
    });

    menu.addEventListener("click", (e) => {
      const opt = e.target.closest('[role="option"]');
      if (!opt) return;
      e.preventDefault();
      pick(opt.getAttribute("data-value"));
    });

    btn.addEventListener("keydown", (e) => {
      if (e.key === "ArrowDown" || e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        openMenu(mount);
        const selected =
          menu.querySelector('[aria-selected="true"]') || menu.querySelector('[role="option"]');
        selected && selected.focus();
      }
    });

    menu.addEventListener("keydown", (e) => {
      const optsEls = Array.from(menu.querySelectorAll('[role="option"]'));
      const i = optsEls.indexOf(document.activeElement);
      if (e.key === "Escape") {
        e.preventDefault();
        closeMenu(mount);
        btn.focus();
        return;
      }
      if (e.key === "ArrowDown") {
        e.preventDefault();
        (optsEls[Math.min(optsEls.length - 1, i + 1)] || optsEls[0]).focus();
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        (optsEls[Math.max(0, i - 1)] || optsEls[0]).focus();
      } else if (e.key === "Home") {
        e.preventDefault();
        optsEls[0] && optsEls[0].focus();
      } else if (e.key === "End") {
        e.preventDefault();
        optsEls[optsEls.length - 1] && optsEls[optsEls.length - 1].focus();
      } else if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        const cur = document.activeElement;
        if (cur && cur.getAttribute("data-value")) pick(cur.getAttribute("data-value"));
      }
    });

    const onDoc = (e) => {
      if (!mount.contains(e.target)) closeMenu(mount);
    };
    document.addEventListener("pointerdown", onDoc);

    root.addEventListener(EVENT, () => {
      paintTrigger(mount, currency());
    });

    mount._currencyCtl = { pick, paint: () => paintTrigger(mount, currency()), close: () => closeMenu(mount) };
    return mount;
  }

  function enhanceCurrencyMounts() {
    document.querySelectorAll("select#home-currency, select[data-currency-select], [data-currency-control]").forEach((el) => {
      if (el.dataset.currencyCtl === "1" || el.closest(".currency-ctl[data-currency-ctl='1']")) return;
      mountCurrency(el);
    });
  }

  state = readStore();

  root.ItineroLocale = {
    STORE_KEY,
    EVENT,
    CURRENCIES,
    detect,
    requestPrecise,
    reset,
    get,
    currency,
    cityLabel,
    setCurrency,
    setHome,
    money,
    convertUsd,
    optionHtml,
    currencyLabel,
    mountCurrency,
    enhanceCurrencyMounts,
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", enhanceCurrencyMounts);
  } else {
    enhanceCurrencyMounts();
  }
})(window);

