  function guestsFaceLabel() {
    var adults = intVal(guestsInput, 2, 1, 14);
    var rooms = intVal(roomsInput, 1, 1, 6);
    var kids = childCount();
    var people = adults + kids;
    var who = people === 1 ? "1 guest" : people + " guests";
    return who + " · " + (rooms === 1 ? "1 room" : rooms + " rooms");
  }

  function childCount() {
    var raw = String((childrenInput && childrenInput.value) || "").trim();
    if (!raw) return 0;
    return raw.split(",").map(function (s) { return s.trim(); }).filter(Boolean).length;
  }

  function childAges() {
    var raw = String((childrenInput && childrenInput.value) || "").trim();
    if (!raw) return [];
    return raw.split(",").map(function (s) {
      var n = parseInt(s, 10);
      return isNaN(n) ? 8 : Math.max(0, Math.min(17, n));
    });
  }

  function setChildren(ages) {
    if (!childrenInput) return;
    childrenInput.value = ages.length ? ages.join(",") : "";
  }

  function stored(key, fallback) {
    try {
      return localStorage.getItem(key) || fallback;
    } catch (_) {
      return fallback;
    }
  }

  function currency() {
    var q = new URLSearchParams(location.search).get("currency");
    return String(q || stored("itinero_currency", "USD")).toUpperCase();
  }

  function language() {
    var q = new URLSearchParams(location.search).get("language");
    return String(q || stored("itinero_language", "en")).toLowerCase();
  }

  /** Natural-language vibe → semantic-search results (not a plain city pin). */
  function looksSemanticQuery(raw) {
    var q = String(raw || "").trim();
    if (q.length < 8) return false;
    var words = q.split(/\s+/).filter(Boolean);
    if (words.length >= 3) return true;
    return (
      words.length >= 2 &&
      /\b(romantic|boutique|luxury|budget|spa|family|quiet|beachfront|ryokan|riad|villa|design|historic|pet[- ]?friendly|near|cozy|charming|rooftop|adults?\s*only|all[- ]inclusive)\b/i.test(
        q
      )
    );
  }

  function resultsHref(city, lat, lng, opts) {
    var dest = String(city || (cityInput && cityInput.value) || "").trim();
    var q = new URLSearchParams();
    if (dest) q.set("destination", dest);
    if (checkinInput && checkinInput.value) q.set("checkin", checkinInput.value);
    if (checkoutInput && checkoutInput.value) q.set("checkout", checkoutInput.value);
    q.set("guests", String(intVal(guestsInput, 2, 1, 14)));
    q.set("rooms", String(intVal(roomsInput, 1, 1, 6)));
    if (childrenInput && childrenInput.value) q.set("children", childrenInput.value);
    q.set("currency", currency());
    q.set("language", language());
    if (lat != null) q.set("lat", String(lat));
    if (lng != null) q.set("lng", String(lng));
    if (opts && opts.semantic) {
      q.set("mode", "semantic");
      q.set("q", String(opts.q || dest));
    }
    return "/hotels/results?" + q.toString();
  }

  function go(city) {
    var dest = String(city || (cityInput && cityInput.value) || "").trim();
    if (!dest) {
      if (statusEl) {
        statusEl.textContent = "Type a city or area to see live stays.";
        statusEl.classList.add("is-error");
      }
      if (cityInput) cityInput.focus();
      return;
    }
    if (statusEl) {
      statusEl.textContent = "Opening live stays…";
      statusEl.classList.remove("is-error");
    }
    // Vibe queries skip geocode → GET /api/hotels/semantic-search on results.
    if (looksSemanticQuery(dest)) {
      location.href = resultsHref(dest, null, null, { semantic: true, q: dest });
      return;
    }
    var lat = selectedPlace.city && selectedPlace.city.toLowerCase() === dest.toLowerCase()
      ? selectedPlace.lat
      : null;
    var lng = lat != null ? selectedPlace.lng : null;
    if (lat != null && lng != null) {
      location.href = resultsHref(dest, lat, lng);
      return;
    }
    fetch("/api/geo/geocode?q=" + encodeURIComponent(dest), {
      credentials: "same-origin",
      headers: { Accept: "application/json" },
    })
      .then(function (r) { return r.json().catch(function () { return {}; }); })
      .catch(function () { return {}; })
      .then(function (data) {
        var pin = data && data.place;
        var pinLat = parseCoord(pin && pin.lat);
        var pinLng = parseCoord(pin && pin.lng);
        if (pin && pinLat != null && pinLng != null) {
          dest = String(pin.name || dest).trim();
          rememberPlace({ city: dest, lat: pinLat, lng: pinLng });
          if (cityInput) cityInput.value = dest;
          location.href = resultsHref(dest, pinLat, pinLng);
          return;
        }
        // Geocode miss on a multi-word query — try semantic rather than empty city search.
        if (looksSemanticQuery(dest) || dest.split(/\s+/).filter(Boolean).length >= 2) {
          location.href = resultsHref(dest, null, null, { semantic: true, q: dest });
          return;
        }
        location.href = resultsHref(dest);
      });
  }

  function syncDockFaces() {
    var startFace = document.getElementById("hx-checkin-face");
    var endFace = document.getElementById("hx-checkout-face");
    var guestsFace = document.getElementById("hx-guests-face");
    if (startFace) startFace.textContent = formatFaceDate(checkinInput && checkinInput.value);
    if (endFace) endFace.textContent = formatFaceDate(checkoutInput && checkoutInput.value);
    if (guestsFace) guestsFace.textContent = guestsFaceLabel();
  }

  function setDefaultDates() {
    var start = new Date();
    start.setDate(start.getDate() + 14);
    var end = new Date(start);
    end.setDate(end.getDate() + 1);
    if (checkinInput && !checkinInput.value) checkinInput.value = isoDate(start);
    if (checkoutInput && !checkoutInput.value) checkoutInput.value = isoDate(end);
    if (checkinInput && checkoutInput && checkoutInput.value <= checkinInput.value) {
      var next = parseIso(checkinInput.value);
      if (next) {
        next.setDate(next.getDate() + 1);
        checkoutInput.value = isoDate(next);
      }
    }
    syncDockFaces();
  }

  function escapeHtml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function applyCover(img, city, kind, fallback) {
    if (!img) return;
    if (fallback && !img.getAttribute("src")) img.src = fallback;
    if (window.ItineroCovers && typeof window.ItineroCovers.apply === "function") {
      window.ItineroCovers.apply(img, city, kind || "hero", fallback);
    }
  }

  function wireDock() {
    var pop = document.getElementById("hx-dock-pop");
    if (!pop) return;
    var state = { kind: "", calKey: "", calMonth: null, suggestReq: 0, suggestTimer: null, lastSuggestItems: [] };

    function closePop() {
      pop.hidden = true;
      pop.innerHTML = "";
      pop.classList.remove("dock-pop--cal");
      document.querySelectorAll("[aria-expanded='true']").forEach(function (el) {
        el.setAttribute("aria-expanded", "false");
      });
      state.kind = "";
      state.calKey = "";
    }

    function placePop(anchor) {
      var aRect = ((anchor.closest && anchor.closest(".cell")) || anchor).getBoundingClientRect();
      var popW = Math.min(340, window.innerWidth - 24);
      pop.style.width = popW + "px";
      pop.style.left = Math.max(12, Math.min(aRect.left, window.innerWidth - popW - 12)) + "px";
      pop.style.top = aRect.bottom + 8 + "px";
      requestAnimationFrame(function () {
        var pr = pop.getBoundingClientRect();
        if (pr.bottom > window.innerHeight - 12) {
          pop.style.top = Math.max(12, aRect.top - pr.height - 8) + "px";
        }
      });
    }

    function openPop(kind, anchor) {
      document.querySelectorAll("[aria-expanded='true']").forEach(function (el) {
        if (el !== anchor) el.setAttribute("aria-expanded", "false");
      });
      if (anchor && anchor.setAttribute) anchor.setAttribute("aria-expanded", "true");
      state.kind = kind;
      pop.classList.toggle("dock-pop--cal", kind === "calendar");
      pop.hidden = false;
      placePop(anchor);
    }

    function applyDate(key, iso) {
      if (key === "start" && checkinInput) checkinInput.value = iso;
      if (key === "end" && checkoutInput) checkoutInput.value = iso;
      if (key === "start" && checkoutInput && (!checkoutInput.value || checkoutInput.value <= iso)) {
        var next = parseIso(iso);
        if (next) {
          next.setDate(next.getDate() + 1);
          checkoutInput.value = isoDate(next);
        }
      }
      if (key === "end" && checkinInput && checkinInput.value && iso <= checkinInput.value) {
        var prev = parseIso(iso);
        if (prev) {
          prev.setDate(prev.getDate() - 1);
          checkinInput.value = isoDate(prev);
        }
      }
      syncDockFaces();
      closePop();
    }

    function renderCalendar(face) {
      var key = face.getAttribute("data-cal") || "start";
      var hidden = key === "end" ? checkoutInput : checkinInput;
      var selected = (hidden && hidden.value) || "";
      var minIso = isoDate(new Date());
      if (key === "end" && checkinInput && checkinInput.value) minIso = checkinInput.value;
      var base = state.calMonth
        ? new Date(state.calMonth.getFullYear(), state.calMonth.getMonth(), 1)
        : selected
          ? parseIso(selected)
          : new Date();
      if (!base) base = new Date();
      state.calMonth = new Date(base.getFullYear(), base.getMonth(), 1);
      var y = state.calMonth.getFullYear();
      var m = state.calMonth.getMonth();
      var firstDow = (new Date(y, m, 1).getDay() + 6) % 7;
      var daysInMonth = new Date(y, m + 1, 0).getDate();
      var todayIso = isoDate(new Date());
      var tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      var tomorrowIso = isoDate(tomorrow);
      var cells = [];
      var i;
      for (i = 0; i < firstDow; i++) cells.push('<span class="dock-pop__day-spacer"></span>');
      for (var d = 1; d <= daysInMonth; d++) {
        var iso = y + "-" + String(m + 1).padStart(2, "0") + "-" + String(d).padStart(2, "0");
        var disabled = iso < minIso;
        cells.push(
          '<button type="button" class="dock-pop__day' +
            (iso === selected ? " is-on" : "") +
            (iso === todayIso ? " is-today" : "") +
            '" data-iso="' +
            iso +
            '"' +
            (disabled ? " disabled" : "") +
            ">" +
            d +
            "</button>"
        );
      }
      openPop("calendar", face);
      pop.innerHTML =
        '<div class="dock-pop__cal"><div class="dock-pop__cal-top"><p class="dock-pop__title">' +
        (key === "end" ? "Check-out" : "Check-in") +
        '</p><p class="dock-pop__picked">' +
        escapeHtml(formatCalTitle(selected || todayIso)) +
        '</p></div><div class="dock-pop__quick">' +
        '<button type="button" class="dock-pop__chip" data-quick="' +
        todayIso +
        '">Today</button>' +
        '<button type="button" class="dock-pop__chip" data-quick="' +
        tomorrowIso +
        '">Tomorrow</button></div>' +
        '<div class="dock-pop__head dock-pop__head--cal">' +
        '<button type="button" class="dock-pop__navbtn" data-nav="-1" aria-label="Previous month">‹</button>' +
        '<p class="dock-pop__month">' +
        escapeHtml(state.calMonth.toLocaleDateString("en-GB", { month: "long", year: "numeric" })) +
        "</p>" +
        '<button type="button" class="dock-pop__navbtn" data-nav="1" aria-label="Next month">›</button></div>' +
        '<div class="dock-pop__week" aria-hidden="true"><span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span><span>Su</span></div>' +
        '<div class="dock-pop__grid">' +
        cells.join("") +
        "</div></div>";
      pop.querySelectorAll("[data-nav]").forEach(function (btn) {
        btn.addEventListener("click", function () {
          state.calMonth = new Date(y, m + Number(btn.getAttribute("data-nav")), 1);
          renderCalendar(face);
        });
      });
      pop.querySelectorAll("[data-quick]").forEach(function (btn) {
        btn.addEventListener("click", function () {
          applyDate(key, btn.getAttribute("data-quick"));
        });
      });
      pop.querySelectorAll(".dock-pop__day[data-iso]").forEach(function (btn) {
        btn.addEventListener("click", function () {
          applyDate(key, btn.getAttribute("data-iso"));
        });
      });
    }

    function renderGuests(face) {
      var adults = intVal(guestsInput, 2, 1, 14);
      var rooms = intVal(roomsInput, 1, 1, 6);
      var ages = childAges();
      openPop("guests", face);
      function paint() {
        pop.innerHTML =
          '<div class="dock-pop__head"><p class="dock-pop__title">Travellers</p></div>' +
          '<div class="dock-pop__pax">' +
          row("Adults", "Ages 18+", "adults", adults, 1, 14) +
          row("Children", "Ages 0–17", "kids", ages.length, 0, 6) +
          row("Rooms", "Max 6", "rooms", rooms, 1, 6) +
          '<button type="button" class="dock-pop__done">Done</button></div>';
        pop.querySelectorAll("[data-field]").forEach(function (btn) {
          btn.addEventListener("click", function () {
            var field = btn.getAttribute("data-field");
            var dir = Number(btn.getAttribute("data-d"));
            if (field === "adults") {
              adults = Math.max(1, Math.min(14, adults + dir));
              if (guestsInput) guestsInput.value = String(adults);
            } else if (field === "rooms") {
              rooms = Math.max(1, Math.min(6, rooms + dir));
              if (roomsInput) roomsInput.value = String(rooms);
            } else {
              var next = ages.length + dir;
              if (next < 0) next = 0;
              if (next > 6) next = 6;
              while (ages.length < next) ages.push(8);
              while (ages.length > next) ages.pop();
              setChildren(ages);
            }
            syncDockFaces();
            paint();
          });
        });
        var done = pop.querySelector(".dock-pop__done");
        if (done) done.addEventListener("click", closePop);
      }
      function row(title, hint, field, value, min, max) {
        return (
          '<div class="dock-pop__row"><div class="dock-pop__row-label"><strong>' +
          title +
          "</strong><span>" +
          hint +
          '</span></div><div class="dock-pop__step"><button type="button" data-field="' +
          field +
          '" data-d="-1" aria-label="Fewer ' +
          title.toLowerCase() +
          '"' +
          (value <= min ? " disabled" : "") +
          ">−</button><b>" +
          value +
          '</b><button type="button" data-field="' +
          field +
          '" data-d="1" aria-label="More ' +
          title.toLowerCase() +
          '"' +
          (value >= max ? " disabled" : "") +
          ">+</button></div></div>"
        );
      }
      paint();
    }

    function paintSuggest(items, q, paintOpts) {
      paintOpts = paintOpts || {};
      if (!items.length) {
        // Never keep prior (unfiltered) suggestions while the typed query changed.
        state.lastSuggestItems = [];
        if (paintOpts.allowEmpty) {
          pop.innerHTML =
            '<p class="dock-pop__empty" style="padding:14px">' +
            (q ? "No matches for “" + escapeHtml(q) + "”." : "Try a city.") +
            "</p>";
          return;
        }
        if (paintOpts.pending || String(q || "").length >= 2) {
          pop.innerHTML = '<p class="dock-pop__empty dock-pop__pending" style="padding:14px" role="status">Searching…</p>';
          return;
        }
        return;
      }
      state.lastSuggestItems = items;
      pop.innerHTML =
        '<ul class="dock-pop__list" role="listbox">' +
        items
          .map(function (d) {
            return (
              '<li><button type="button" class="dock-pop__opt" data-city="' +
              escapeHtml(d.city) +
              '" data-lat="' +
              (d.lat != null ? String(d.lat) : "") +
              '" data-lng="' +
              (d.lng != null ? String(d.lng) : "") +
              '"><span class="dock-pop__copy"><span class="dock-pop__city">' +
              escapeHtml(d.city) +
              '</span><span class="dock-pop__meta">' +
              escapeHtml(d.tag || "") +
              "</span></span></button></li>"
            );
          })
          .join("") +
        "</ul>";
      pop.querySelectorAll(".dock-pop__opt").forEach(function (btn) {
        btn.addEventListener("mousedown", function (ev) {
          ev.preventDefault();
        });
        btn.addEventListener("click", function () {
          rememberPlace({
            city: btn.getAttribute("data-city") || "",
            lat: btn.getAttribute("data-lat"),
            lng: btn.getAttribute("data-lng"),
          });
          cityInput.value = selectedPlace.city;
          applyCover(heroImg, cityInput.value, "hero", heroImg && heroImg.getAttribute("src"));
          closePop();
          cityInput.focus();
        });
      });
    }

    function mapPlaceRows(list, fallbackTag) {
      return (Array.isArray(list) ? list : [])
        .map(function (p) {
          var title = String(p.name || p.city || "").trim();
          var sub = String(p.subtitle || p.address || p.label || p.country || "").trim();
          return {
            city: title,
            tag: sub && sub !== title ? sub : fallbackTag,
            lat: parseCoord(p.lat != null ? p.lat : p.latitude),
            lng: parseCoord(p.lng != null ? p.lng : p.longitude),
            kind: String(p.kind || "").toLowerCase(),
          };
        })
        .filter(function (r) { return r.city; });
    }

    function destRows(rows) {
      var prefer = { place: 1, city: 1, locality: 1, region: 1, district: 1, neighborhood: 1, country: 1 };
      var dest = (rows || []).filter(function (row) {
        return !row.kind || prefer[row.kind];
      });
      return dest.length ? dest : rows;
    }

    function mapGeoRows(data) {
      var items = [];
      if (data && data.place) items.push(data.place);
      (data && data.items ? data.items : []).forEach(function (item) { items.push(item); });
      return destRows(mapPlaceRows(items, "Destination"));
    }

    function mergeSuggest(a, b) {
      var seen = {};
      var out = [];
      destRows((a || []).concat(b || [])).forEach(function (row) {
        var key = [
          String(row.city || "").toLowerCase(),
          row.lat != null ? row.lat.toFixed(2) : "",
          row.lng != null ? row.lng.toFixed(2) : "",
        ].join("|");
        if (!row.city || seen[key]) return;
        seen[key] = 1;
        out.push(row);
      });
      return out.slice(0, 8);
    }

    function renderSuggest() {
      if (!cityInput) return;
      var q = cityInput.value.trim();
      var qAtStart = q;
      openPop("suggest", cityInput);
      var local = DESTINATIONS.filter(function (d) {
        return !q || d.city.toLowerCase().indexOf(q.toLowerCase()) !== -1;
      }).slice(0, 8);
      if (q.length < 2) {
        paintSuggest(local, q);
        return;
      }
      if (local.length) paintSuggest(local, q);
      else paintSuggest([], q, { pending: true });
      var req = ++state.suggestReq;
      var ds = window.ItineroDestinationSuggest;
      var finish = function (rows, settled) {
        if (req !== state.suggestReq || state.kind !== "suggest") return;
        if (cityInput.value.trim() !== qAtStart) return;
        var mapped = (rows || []).map(function (row) {
          return {
            city: row.city || row.title,
            tag: row.tag || row.sub || "Stay here",
            label: row.label || row.title,
            lat: row.lat,
            lng: row.lng,
          };
        });
        if (mapped.length || local.length) paintSuggest(mapped.length ? mapped : local, qAtStart);
        else if (settled) paintSuggest([], qAtStart, { allowEmpty: true });
      };
      if (ds && typeof ds.query === "function") {
        ds.query(q, {
          mode: "hotel",
          limit: 8,
          onPartial: function (rows) {
            if (req !== state.suggestReq || state.kind !== "suggest") return;
            finish(rows, false);
          },
        }).then(function (payload) {
          finish(payload.rows || [], true);
        }).catch(function () {
          finish(local, true);
        });
        return;
      }
      var headers = { Accept: "application/json" };
      Promise.all([
        fetch("/api/places/suggest?q=" + encodeURIComponent(q) + "&limit=8", { credentials: "same-origin", headers: headers })
          .then(function (r) { return r.json().catch(function () { return {}; }); })
          .catch(function () { return {}; }),
        fetch("/api/geo/search?q=" + encodeURIComponent(q) + "&limit=8", { credentials: "same-origin", headers: headers })
          .then(function (r) { return r.json().catch(function () { return {}; }); })
          .catch(function () { return {}; }),
        fetch("/api/geo/geocode?q=" + encodeURIComponent(q), { credentials: "same-origin", headers: headers })
          .then(function (r) { return r.json().catch(function () { return {}; }); })
          .catch(function () { return {}; }),
      ]).then(function (pair) {
        if (req !== state.suggestReq || state.kind !== "suggest") return;
        var places = mapPlaceRows(pair[0] && pair[0].places, "Stay here");
        var geo = mapGeoRows(pair[1] || {});
        var pin = mapGeoRows(pair[2] || {});
        var rows = mergeSuggest(mergeSuggest(pin, places), geo);
        finish(rows, true);
      });
    }

    var startFace = document.getElementById("hx-checkin-face");
    var endFace = document.getElementById("hx-checkout-face");
    var guestsFace = document.getElementById("hx-guests-face");
    if (startFace) startFace.addEventListener("click", function () { state.calMonth = null; renderCalendar(startFace); });
    if (endFace) endFace.addEventListener("click", function () { state.calMonth = null; renderCalendar(endFace); });
    if (guestsFace) guestsFace.addEventListener("click", function () { renderGuests(guestsFace); });
    if (cityInput) {
      cityInput.addEventListener("focus", renderSuggest);
      cityInput.addEventListener("input", function () {
        var q = cityInput.value.trim();
        if (!selectedPlace.city || selectedPlace.city.toLowerCase() !== q.toLowerCase()) {
          rememberPlace({ city: q });
        }
        openPop("suggest", cityInput);
        var local = DESTINATIONS.filter(function (d) {
          return !q || d.city.toLowerCase().indexOf(q.toLowerCase()) !== -1;
        }).slice(0, 8);
        if (local.length) paintSuggest(local, q);
        else if (q.length >= 2) paintSuggest([], q, { pending: true });
        clearTimeout(state.suggestTimer);
        var wait = (window.ItineroDestinationSuggest && window.ItineroDestinationSuggest.DEBOUNCE_MS) || 200;
        state.suggestTimer = setTimeout(renderSuggest, wait);
      });
    }
    document.addEventListener("mousedown", function (ev) {
      if (pop.hidden) return;
      if (pop.contains(ev.target) || (ev.target.closest && ev.target.closest(".cell"))) return;
      closePop();
    });
    document.addEventListener("keydown", function (ev) {
      if (ev.key === "Escape" && !pop.hidden) closePop();
    });
    window.addEventListener("resize", function () {
      if (!pop.hidden) closePop();
    });
  }

  function wireNights() {
    if (!nights) return;
    nights.addEventListener("click", function (ev) {
      var btn = ev.target.closest(".hx-stay");
      if (!btn) return;
      var city = btn.getAttribute("data-city") || "";
      rememberPlace({
        city: city,
        lat: btn.getAttribute("data-lat"),
        lng: btn.getAttribute("data-lng"),
      });
      if (cityInput) cityInput.value = city;
      applyCover(heroImg, city, "hero", heroImg && heroImg.getAttribute("src"));
      go(city);
    });
  }

  function wireVero() {
    var formEl = document.getElementById("hx-vero-form");
    if (!formEl) return;
    var input = document.getElementById("hx-vero-input");
    function ask(q) {
      q = String(q || "").trim();
      location.href = "/vero/?q=" + encodeURIComponent(q);
    }
    formEl.addEventListener("submit", function (ev) {
      ev.preventDefault();
