    }
    document.addEventListener("mousedown", function (ev) {
      if (pop.hidden) return;
      if (pop.contains(ev.target) || (ev.target.closest && ev.target.closest(".cell"))) return;
      closePop();
    });
    document.addEventListener("keydown", function (ev) {
      if (ev.key === "Escape" && !pop.hidden) closePop();
    });
    window.addEventListener("resize", function () {
      if (!pop.hidden) closePop();
    });
  }

  function wireNights() {
    if (!nights) return;
    nights.addEventListener("click", function (ev) {
      var btn = ev.target.closest(".hx-stay");
      if (!btn) return;
      var city = btn.getAttribute("data-city") || "";
      rememberPlace({
        city: city,
        lat: btn.getAttribute("data-lat"),
        lng: btn.getAttribute("data-lng"),
      });
      if (cityInput) cityInput.value = city;
      applyCover(heroImg, city, "hero", heroImg && heroImg.getAttribute("src"));
      go(city);
    });
  }

  function wireVero() {
    var formEl = document.getElementById("hx-vero-form");
    if (!formEl) return;
    var input = document.getElementById("hx-vero-input");
    function ask(q) {
      q = String(q || "").trim();
      location.href = "/vero/?q=" + encodeURIComponent(q);
    }
    formEl.addEventListener("submit", function (ev) {
      ev.preventDefault();
      ask(input && input.value);
    });
    document.querySelectorAll(".hx-vero__chips [data-invite]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        ask(btn.getAttribute("data-invite"));
      });
    });
  }

  function boot() {
    document.body.dataset.listLoading = "0";
    document.body.dataset.listIdle = "1";
    setDefaultDates();
    wireDock();
    wireNights();
    wireVero();
    if (form) {
      form.addEventListener("submit", function (ev) {
        ev.preventDefault();
        go();
      });
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

