/* Flights landing: only what the shared Experiences hero/dock does not already provide. */
.fl-trip {
  display: flex;
  gap: 8px;
  margin-bottom: 12px;
}
.fl-trip .dock-pop__chip {
  padding: 7px 16px;
  font-size: var(--text-sm, 0.8125rem);
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.4);
}

.fl-dock .dock__fields {
  grid-template-columns: 1.25fr 1.25fr 1fr 1fr 1.25fr;
}
.fl-dock.is-oneway .dock__fields {
  grid-template-columns: 1.3fr 1.3fr 1fr 1.25fr;
}
.fl-dock .cell[hidden] { display: none; }

.cell--from {
  position: relative;
  padding-right: 44px;
}
.fl-swap {
  position: absolute;
  top: 50%;
  right: 8px;
  transform: translateY(-50%);
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.25s;
}
.fl-swap:hover { background: rgba(255, 255, 255, 0.18); }
.fl-swap:active { transform: translateY(-50%) rotate(180deg); }
.fl-swap:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.45);
  outline-offset: 2px;
}

.fl-page .dock-pop:not(.dock-pop--cal) {
  overflow-y: auto;
  max-height: min(360px, calc(100vh - 24px));
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.35) transparent;
}
.fl-page .dock-pop:not(.dock-pop--cal) .dock-pop__list {
  max-height: none;
  overflow: visible;
}
.dock-pop__code {
  flex: 0 0 auto;
  min-width: 3ch;
  font-size: var(--text-xs, 0.75rem);
  font-weight: 800;
  letter-spacing: 0.06em;
  color: rgba(255, 255, 255, 0.72);
}
.dock-pop__cabins {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

@media (max-width: 820px) {
  .fl-dock .dock__fields,
  .fl-dock.is-oneway .dock__fields {
    grid-template-columns: 1fr 1fr;
  }
  .fl-trip { justify-content: flex-start; }
  .cell--from { padding-right: 44px; }
  .fl-dock.is-oneway .cell--date {
    grid-column: 1 / -1;
    border-right: 0;
  }
}

@media (max-width: 640px) {
  .fl-wrap,
  .fl-rail { width: min(1180px, calc(100% - 32px)); max-width: 100%; }
  .fl-page .cell input,
  .fl-page .cell__face { font-size: 16px; }
  .fl-vero {
    padding: 22px 16px 20px;
    border-radius: 22px;
    gap: 18px;
    overflow: hidden;
  }
  .fl-vero h2 { font-size: 1.45rem; }
  .fl-vero__copy p:not(.fl-vero__badge) {
    font-size: 1rem;
    max-width: none;
  }
  .fl-vero__form {
    flex-direction: column;
    align-items: stretch;
    border-radius: 18px;
    padding: 8px;
    min-height: 0;
    gap: 8px;
  }
  .fl-vero__form input {
    font-size: 16px;
    padding: 10px 12px;
    min-height: 44px;
  }
  .fl-vero__form .vero-cta {
    width: 100%;
    justify-content: center;
    min-width: 0;
  }
  .fl-cross__card { min-height: 180px; aspect-ratio: 16 / 9; }
  .fl-page .dock-pop:not(.dock-pop--cal) {
    left: 8px !important;
    right: 8px !important;
    width: auto !important;
    max-width: none;
  }
}

/* Sections below the hero */
.fl-wrap { width: min(1180px, calc(100% - 48px)); margin: 0 auto; }
.fl-band { padding: clamp(56px, 7vw, 96px) 0; background: var(--bg, #fff); color: var(--ink, #0b1b33); }
.fl-kicker { margin: 0; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #e8772e; }
.fl-head { max-width: 640px; margin-bottom: clamp(24px, 3.5vw, 40px); }
.fl-head h2, .fl-page .xp-assurance h2 { margin: 6px 0 10px; font-size: clamp(1.75rem, 3vw, 2.375rem); line-height: 1.1; letter-spacing: -0.02em; font-weight: 700; color: var(--ink, #0b1b33); }
.fl-head p:not(.fl-kicker) { margin: 0; max-width: 52ch; color: var(--muted, #5b6b82); font-size: 1.0625rem; line-height: 1.55; }

/* Contain dest rail: cards may extend past the viewport for snap-scroll, but must not widen the page */
.fl-dest-band {
  padding-bottom: clamp(48px, 6vw, 80px);
  max-width: 100%;
  overflow-x: clip;
  overflow-y: visible;
}
/* Scroll rail — fixed cards + snap; overflow stays inside the rail, never the document */
.fl-rail {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(200px, 220px);
  gap: 14px;
  box-sizing: border-box;
  width: min(1180px, calc(100% - 48px));
  max-width: 100%;
  min-width: 0;
  margin: 0 auto;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
  padding-bottom: 8px;
  scrollbar-width: thin;
  scrollbar-color: rgba(15, 23, 42, 0.28) transparent;
}
.fl-rail::-webkit-scrollbar { height: 6px; }
.fl-rail::-webkit-scrollbar-thumb { background: rgba(15, 23, 42, 0.28); border-radius: 999px; }
.fl-dest, .fl-cross__card { position: relative; display: block; overflow: hidden; border-radius: 22px; color: #fff; text-decoration: none; background: #0b1b33; isolation: isolate; box-shadow: 0 0 0 1px rgba(15, 23, 42, 0.06), 0 16px 40px rgba(0, 20, 56, 0.14); }
.fl-dest { aspect-ratio: 3 / 4.2; scroll-snap-align: start; min-width: 0; max-width: 100%; }
.fl-dest img, .fl-cross__card img { position: absolute; inset: 0; width: 100%; height: 100%; max-width: 100%; object-fit: cover; z-index: -3; filter: saturate(0.88) contrast(1.06) brightness(0.92); transition: transform 0.7s cubic-bezier(.2,.7,.2,1); }
.fl-dest::before { content: ""; position: absolute; inset: 0; z-index: -2; background: linear-gradient(180deg, rgba(14,30,66,0.35) 0%, rgba(232,119,46,0.12) 100%); mix-blend-mode: soft-light; }
/* Dual scrim — fork-band bar: type stays readable on bright imagery; stay inside card bounds */
.fl-dest__shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  max-width: 100%;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(0,8,20,0.28) 0%, rgba(0,8,20,0.06) 22%, rgba(0,6,14,0.52) 42%, rgba(0,4,10,0.82) 62%, rgba(0,2,6,0.94) 82%, rgba(0,0,0,0.97) 100%);
}
.fl-dest__txt { position: absolute; left: 18px; right: 18px; bottom: 18px; display: flex; flex-direction: column; gap: 3px; }
.fl-dest__txt em { font-style: normal; font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.14em; color: #f2a56b; text-shadow: 0 1px 10px rgba(0,0,0,0.45); }
.fl-dest__txt strong { font-size: 1.5rem; font-weight: 700; letter-spacing: -0.015em; text-shadow: 0 2px 18px rgba(0,0,0,0.55); }
.fl-dest__txt span, .fl-cross__card .fl-dest__txt span { font-size: 0.8125rem; line-height: 1.35; color: rgba(255,255,255,0.92); text-shadow: 0 1px 12px rgba(0,0,0,0.5); }
/* Always-visible solid CTA — not hover-only dead chrome */
.fl-dest__go { position: absolute; top: 14px; right: 14px; display: inline-flex; align-items: center; gap: 6px; padding: 8px 14px; border-radius: 999px; font-size: 0.75rem; font-weight: 750; background: #fff; color: #0b1b33; opacity: 1; transform: none; box-shadow: 0 8px 22px rgba(0,0,0,0.28); transition: background 0.2s, box-shadow 0.2s; }
.fl-dest:hover img, .fl-cross__card:hover img { transform: scale(1.06); }
.fl-dest:hover .fl-dest__go, .fl-cross__card:hover .fl-dest__go { background: #f8fafc; box-shadow: 0 10px 26px rgba(0,0,0,0.32); }
.fl-dest:focus-visible, .fl-cross__card:focus-visible { outline: 3px solid #e8772e; outline-offset: 3px; }

.fl-vero-band { background: var(--bg, #fff); padding-top: 0; }
.fl-vero { position: relative; display: grid; grid-template-columns: 0.85fr 1.15fr; gap: clamp(24px, 4vw, 56px); align-items: center; padding: clamp(28px, 4vw, 52px); border-radius: 28px; border: 1.5px solid transparent; color: #fff;
  background: radial-gradient(900px 300px at 12% 0%, rgba(249, 114, 17,0.22), transparent 60%), radial-gradient(700px 300px at 100% 100%, rgba(251,146,60,0.18), transparent 60%), linear-gradient(160deg, #081530, #050d20) padding-box, linear-gradient(var(--ai-ring, 120deg, #c084fc, #fb9a4d, #fb923c)) border-box;
  box-shadow: 0 0 0 1px rgba(249, 114, 17,0.2), 0 24px 60px rgba(88,28,135,0.18); }
.fl-vero__badge { display: inline-flex; align-items: center; gap: 10px; margin: 0 0 16px; font-size: 0.75rem; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: rgba(255,255,255,0.7); }
.fl-vero__badge span { display: inline-flex; align-items: center; gap: 5px; height: 22px; padding: 0 9px 0 7px; border-radius: 999px; background: #fff; color: #6d28d9; font-weight: 800; }
.fl-vero h2 { margin: 0 0 12px; font-size: clamp(1.625rem, 2.8vw, 2.25rem); line-height: 1.12; letter-spacing: -0.02em; font-weight: 700; color: #fff; }
.fl-vero__copy p:not(.fl-vero__badge) { margin: 0; max-width: 40ch; color: rgba(255,255,255,0.72); line-height: 1.55; font-size: 1.0625rem; }
.fl-vero__form { display: flex; gap: 8px; align-items: center; min-height: 60px; padding: 7px 7px 7px 20px; border-radius: 999px; background: rgba(255,255,255,0.08); border: 1px solid rgba(255,255,255,0.18); transition: border-color 0.2s, box-shadow 0.2s; }
.fl-vero__form:focus-within { border-color: #d8b4fe; box-shadow: 0 0 0 4px rgba(249, 114, 17,0.18); }
.fl-vero__form input { flex: 1; text-overflow: ellipsis; min-width: 0; border: 0; outline: 0; background: transparent; color: #fff; font: inherit; font-size: 1rem; }
.fl-vero__form input::placeholder { color: rgba(255,255,255,0.68); }
.fl-vero__try { margin: 20px 0 10px 4px; font-size: 0.6875rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: rgba(255,255,255,0.5); }
.fl-vero__chips { display: flex; flex-wrap: wrap; gap: 8px; }
.fl-vero__chips button { padding: 9px 15px; border-radius: 999px; border: 1px solid rgba(255,255,255,0.18); background: rgba(255,255,255,0.05); color: rgba(255,255,255,0.88); font: inherit; font-size: 0.8125rem; font-weight: 600; cursor: pointer; transition: background 0.15s, border-color 0.15s; }
.fl-vero__chips button:hover { background: rgba(255,255,255,0.12); border-color: #d8b4fe; }
.fl-vero__chips button:focus-visible { outline: 2px solid #d8b4fe; outline-offset: 2px; }

/* minmax(0,1fr) — intrinsic img/aspect-ratio must not expand body scrollWidth at 390 */
.fl-cross {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 14px;
  min-width: 0;
  max-width: 100%;
}
.fl-cross__card {
  aspect-ratio: 16 / 7;
  min-height: 220px;
  min-width: 0;
  max-width: 100%;
  width: 100%;
}
.fl-cross__card .fl-dest__txt strong { font-size: 1.5rem; }

.fl-faq { border-top: 1px solid var(--line, #e3e8ef); }
.fl-faq__in { display: grid; grid-template-columns: 1fr 1.5fr; gap: clamp(24px, 5vw, 80px); align-items: start; }
.fl-faq .fl-head { margin-bottom: 0; }
.fl-faq__list { border-top: 1px solid var(--line, #e3e8ef); }
.fl-faq__item { border-bottom: 1px solid var(--line, #e3e8ef); }
.fl-faq__item summary { list-style: none; cursor: pointer; padding: 20px 36px 20px 0; position: relative; font-weight: 600; font-size: 1.0625rem; color: var(--ink, #0b1b33); }
.fl-faq__item summary::-webkit-details-marker { display: none; }
.fl-faq__item summary::after { content: ""; position: absolute; right: 6px; top: 50%; width: 9px; height: 9px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: translateY(-70%) rotate(45deg); transition: transform 0.2s; }
.fl-faq__item[open] summary::after { transform: translateY(-30%) rotate(-135deg); }
.fl-faq__item summary:focus-visible { outline: 3px solid #e8772e; outline-offset: 2px; }
.fl-faq__item p { margin: 0 0 20px; padding-right: 36px; color: var(--muted, #5b6b82); line-height: 1.6; }

@media (max-width: 960px) {
  .fl-faq__in, .fl-vero { grid-template-columns: minmax(0, 1fr); }
  .fl-cross { grid-template-columns: minmax(0, 1fr); }
  .fl-rail { grid-auto-columns: minmax(200px, 62%); }
}
@media (max-width: 560px) { .fl-rail { grid-auto-columns: minmax(200px, 78%); } .fl-dest__go { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) { .fl-dest img, .fl-cross__card img { transition: none; } }

html[data-theme="dark"] .fl-page .cell input,
html[data-theme="dark"] .fl-page .fl-vero__form input {
  background: transparent;
  color: #fff;
  border-color: transparent;
}
html[data-theme="dark"] .fl-page .cell input::placeholder,
html[data-theme="dark"] .fl-page .fl-vero__form input::placeholder {
  color: rgba(255, 255, 255, 0.68);
}
html[data-theme="dark"] .fl-band,
html[data-theme="dark"] .fl-vero-band {
  background: var(--bg, #070d16);
  color: var(--ink, #e8eef6);
}
html[data-theme="dark"] .fl-head h2,
html[data-theme="dark"] .fl-page .xp-assurance h2,
html[data-theme="dark"] .fl-faq__item summary {
  color: var(--ink, #e8eef6);
}
html[data-theme="dark"] .fl-head p:not(.fl-kicker),
html[data-theme="dark"] .fl-faq__item p {
  color: var(--muted, #b6c4d6);
}
html[data-theme="dark"] .fl-faq,
html[data-theme="dark"] .fl-faq__list,
html[data-theme="dark"] .fl-faq__item {
  border-color: var(--line, #2a3b55);
}
html[data-theme="dark"] .fl-rail {
  scrollbar-color: rgba(232, 238, 246, 0.28) transparent;
}
html[data-theme="dark"] .fl-rail::-webkit-scrollbar-thumb {
  background: rgba(232, 238, 246, 0.28);
}

