    location.href = "/flights/results/?" + q.toString();
  }

  function prefillFromQuery() {
    var q = new URLSearchParams(location.search);
    function seed(which, input, param) {
      var code = String(q.get(param) || "").toUpperCase();
      if (!/^[A-Z]{3}$/.test(code)) return false;
      var hit = AIRPORTS.filter(function (a) { return a[0] === code; })[0];
      picked[which] = code;
      input.value = hit ? hit[1] + " (" + code + ")" : code;
      return true;
    }
    seed("from", fromInput, "from");
    seed("to", toInput, "to");
    if (q.get("depart")) departInput.value = q.get("depart");
    if (q.get("return")) returnInput.value = q.get("return");
    var adults = parseInt(q.get("adults"), 10);
    if (adults >= 1) adultsInput.value = String(Math.min(9, adults));
    var cabin = String(q.get("cabin") || "").toUpperCase();
    if (CABINS.some(function (c) { return c[0] === cabin; })) cabinInput.value = cabin;
    return q.get("trip") === "round" || !!q.get("return");
  }

  function seedHomeAirport() {
    if (fromInput.value) return;
    var loc = window.ItineroLocale && window.ItineroLocale.get && window.ItineroLocale.get();
    var code = String((loc && loc.airport) || "").toUpperCase();
    if (!/^[A-Z]{3}$/.test(code) || fromInput.value) return;
    var hit = AIRPORTS.filter(function (a) { return a[0] === code; })[0];
    picked.from = code;
    fromInput.value = hit ? hit[1] + " (" + code + ")" : code;
  }

  function init() {
    var round = prefillFromQuery();
    if (!departInput.value) departInput.value = addDays(isoDate(new Date()), 14);
    setTrip(round ? "round" : "oneway");

    document.querySelectorAll("#fl-trip [data-trip]").forEach(function (btn) {
      btn.addEventListener("click", function () { setTrip(btn.getAttribute("data-trip")); });
    });
    document.getElementById("fl-swap").addEventListener("click", function (ev) {
      ev.preventDefault();
      swap();
    });
    departFace.addEventListener("click", function () { state.calMonth = null; renderCalendar(departFace); });
    returnFace.addEventListener("click", function () { state.calMonth = null; renderCalendar(returnFace); });
    paxFace.addEventListener("click", function () { renderPax(paxFace); });
    [["from", fromInput], ["to", toInput]].forEach(function (pair) {
      var which = pair[0];
      var input = pair[1];
      input.addEventListener("focus", function () { renderAirports(which); });
      input.addEventListener("input", function () {
        picked[which] = "";
        renderAirports(which);
      });
      input.addEventListener("keydown", function (ev) {
        if (ev.key !== "Enter") return;
        var first = pop.querySelector(".dock-pop__opt");
        if (!pop.hidden && state.kind === "suggest" && first) {
          ev.preventDefault();
          first.click();
        }
      });
    });
    form.addEventListener("submit", submit);
    document.addEventListener("mousedown", function (ev) {
      if (pop.hidden) return;
      if (pop.contains(ev.target) || (ev.target.closest && ev.target.closest(".cell"))) return;
