    ["JNB", "Johannesburg", "O. R. Tambo Intl", "South Africa"],
  ];

  var CABINS = [
    ["ECONOMY", "Economy"],
    ["PREMIUM_ECONOMY", "Premium economy"],
    ["BUSINESS", "Business"],
    ["FIRST", "First"],
  ];

  var form = document.getElementById("fl-search-form");
  var dock = document.getElementById("fl-dock");
  var pop = document.getElementById("fl-dock-pop");
  var statusEl = document.getElementById("fl-status");
  var fromInput = document.getElementById("fl-from");
  var toInput = document.getElementById("fl-to");
  var departInput = document.getElementById("fl-depart");
  var returnInput = document.getElementById("fl-return");
  var returnCell = document.getElementById("fl-return-cell");
  var adultsInput = document.getElementById("fl-adults");
  var cabinInput = document.getElementById("fl-cabin");
  var departFace = document.getElementById("fl-depart-face");
  var returnFace = document.getElementById("fl-return-face");
  var paxFace = document.getElementById("fl-pax-face");
  if (!form || !pop) return;

  var state = { trip: "oneway", kind: "", calMonth: null, req: 0 };
  var picked = { from: "", to: "" };

  function escapeHtml(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function isoDate(d) {
    return (
      d.getFullYear() +
      "-" +
      String(d.getMonth() + 1).padStart(2, "0") +
      "-" +
      String(d.getDate()).padStart(2, "0")
    );
  }

  function parseIso(iso) {
    if (!iso) return null;
    var d = new Date(String(iso) + "T12:00:00");
    return isNaN(d.getTime()) ? null : d;
  }

  function addDays(iso, n) {
    var d = parseIso(iso) || new Date();
    d.setDate(d.getDate() + n);
    return isoDate(d);
  }

  function formatFaceDate(iso) {
    var d = parseIso(iso);
    if (!d) return "Select date";
    return (
      String(d.getDate()).padStart(2, "0") +
      " " +
      d.toLocaleDateString("en-GB", { month: "short" }) +
      " " +
      d.getFullYear()
    );
  }

  function formatCalTitle(iso) {
    var d = parseIso(iso);
    if (!d) return "Select a date";
    return d.toLocaleDateString("en-GB", { weekday: "short", day: "numeric", month: "long", year: "numeric" });
  }

  function cabinLabel(code) {
    var hit = CABINS.filter(function (c) { return c[0] === code; })[0];
    return hit ? hit[1] : "Economy";
  }

  function syncFaces() {
    departFace.textContent = formatFaceDate(departInput.value);
    returnFace.textContent = formatFaceDate(returnInput.value);
    var n = parseInt(adultsInput.value, 10) || 1;
    paxFace.textContent = (n === 1 ? "1 traveller" : n + " travellers") + " · " + cabinLabel(cabinInput.value);
  }

  function setStatus(msg, kind) {
    statusEl.textContent = msg || "";
    statusEl.classList.toggle("is-error", kind === "error");
  }

  function setTrip(trip) {
    state.trip = trip === "round" ? "round" : "oneway";
    dock.classList.toggle("is-oneway", state.trip === "oneway");
    returnCell.hidden = state.trip !== "round";
    document.querySelectorAll("#fl-trip [data-trip]").forEach(function (btn) {
      var on = btn.getAttribute("data-trip") === state.trip;
      btn.classList.toggle("is-on", on);
      btn.setAttribute("aria-checked", on ? "true" : "false");
    });
    if (state.trip === "round" && (!returnInput.value || returnInput.value < departInput.value)) {
      returnInput.value = addDays(departInput.value, 7);
    }
    syncFaces();
  }

  /* Popover plumbing (same placement + dismissal as the Experiences dock) */
  function closePop() {
    pop.hidden = true;
    pop.innerHTML = "";
    pop.classList.remove("dock-pop--cal");
    document.querySelectorAll("#fl-dock [aria-expanded='true']").forEach(function (el) {
      el.setAttribute("aria-expanded", "false");
    });
    state.kind = "";
  }

  function placePop(anchor) {
    var rect = (anchor.closest(".cell") || anchor).getBoundingClientRect();
    var w = Math.min(340, window.innerWidth - 24);
    pop.style.width = w + "px";
    pop.style.left = Math.max(12, Math.min(rect.left, window.innerWidth - w - 12)) + "px";
    pop.style.top = rect.bottom + 8 + "px";
    requestAnimationFrame(function () {
      var pr = pop.getBoundingClientRect();
      if (pr.bottom > window.innerHeight - 12) {
        pop.style.top = Math.max(12, rect.top - pr.height - 8) + "px";
      }
    });
  }

  function openPop(kind, anchor) {
    document.querySelectorAll("#fl-dock [aria-expanded='true']").forEach(function (el) {
      if (el !== anchor) el.setAttribute("aria-expanded", "false");
    });
    anchor.setAttribute("aria-expanded", "true");
    state.kind = kind;
    pop.classList.toggle("dock-pop--cal", kind === "calendar");
    pop.hidden = false;
    placePop(anchor);
  }

  /* Calendar */
  function applyDate(key, iso) {
    if (key === "depart") {
      departInput.value = iso;
      if (state.trip === "round" && (!returnInput.value || returnInput.value < iso)) {
        returnInput.value = addDays(iso, 7);
      }
    } else {
      returnInput.value = iso;
      if (departInput.value && iso < departInput.value) departInput.value = iso;
    }
    syncFaces();
    closePop();
    if (key === "depart" && state.trip === "round") returnFace.click();
  }

  function renderCalendar(face) {
    var key = face.getAttribute("data-cal");
    var hidden = key === "return" ? returnInput : departInput;
    var selected = hidden.value || "";
    var todayIso = isoDate(new Date());
    var minIso = key === "return" && departInput.value ? departInput.value : todayIso;
    var base = state.calMonth || parseIso(selected) || new Date();
    state.calMonth = new Date(base.getFullYear(), base.getMonth(), 1);
    var y = state.calMonth.getFullYear();
    var m = state.calMonth.getMonth();
    var firstDow = (new Date(y, m, 1).getDay() + 6) % 7;
    var daysInMonth = new Date(y, m + 1, 0).getDate();
    var cells = [];
    for (var i = 0; i < firstDow; i++) cells.push('<span class="dock-pop__day-spacer"></span>');
    for (var d = 1; d <= daysInMonth; d++) {
      var iso = y + "-" + String(m + 1).padStart(2, "0") + "-" + String(d).padStart(2, "0");
      cells.push(
        '<button type="button" class="dock-pop__day' +
          (iso === selected ? " is-on" : "") +
          (iso === todayIso ? " is-today" : "") +
          '" data-iso="' + iso + '"' + (iso < minIso ? " disabled" : "") + ">" + d + "</button>"
      );
    }
    openPop("calendar", face);
    window.ItineroCalendar.mount(pop, { value: selected, min: minIso, onPick: function (iso) { applyDate(key, iso); } });
    return;
    pop.innerHTML =
      '<div class="dock-pop__cal"><div class="dock-pop__cal-top"><p class="dock-pop__title">' +
      (key === "return" ? "Return" : "Depart") +
      '</p><p class="dock-pop__picked">' +
      escapeHtml(formatCalTitle(selected || minIso)) +
      '</p></div><div class="dock-pop__quick">' +
      '<button type="button" class="dock-pop__chip" data-quick="' + addDays(todayIso, 7) + '">In a week</button>' +
      '<button type="button" class="dock-pop__chip" data-quick="' + addDays(todayIso, 30) + '">In a month</button></div>' +
      '<div class="dock-pop__head dock-pop__head--cal">' +
      '<button type="button" class="dock-pop__navbtn" data-nav="-1" aria-label="Previous month">‹</button>' +
      '<p class="dock-pop__month">' +
      escapeHtml(state.calMonth.toLocaleDateString("en-GB", { month: "long", year: "numeric" })) +
      "</p>" +
      '<button type="button" class="dock-pop__navbtn" data-nav="1" aria-label="Next month">›</button></div>' +
      '<div class="dock-pop__week" aria-hidden="true"><span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span><span>Su</span></div>' +
      '<div class="dock-pop__grid">' + cells.join("") + "</div></div>";
    pop.querySelectorAll("[data-nav]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        state.calMonth = new Date(y, m + Number(btn.getAttribute("data-nav")), 1);
        renderCalendar(face);
      });
    });
    pop.querySelectorAll("[data-quick]").forEach(function (btn) {
      btn.addEventListener("click", function () {
        var iso = btn.getAttribute("data-quick");
        applyDate(key, iso < minIso ? minIso : iso);
      });
    });
    pop.querySelectorAll(".dock-pop__day[data-iso]").forEach(function (btn) {
      btn.addEventListener("click", function () { applyDate(key, btn.getAttribute("data-iso")); });
    });
  }

  /* Travellers + cabin */
  function renderPax(face) {
    openPop("pax", face);
    function paint() {
      var n = parseInt(adultsInput.value, 10) || 1;
      pop.innerHTML =
        '<div class="dock-pop__head"><p class="dock-pop__title">Travellers</p></div>' +
        '<div class="dock-pop__pax"><div class="dock-pop__row"><div class="dock-pop__row-label"><strong>Adults</strong><span>12+</span></div>' +
        '<div class="dock-pop__step"><button type="button" data-d="-1" aria-label="Fewer adults"' + (n <= 1 ? " disabled" : "") + ">−</button><b>" + n +
        '</b><button type="button" data-d="1" aria-label="More adults"' + (n >= 9 ? " disabled" : "") + ">+</button></div></div>" +
        '<div class="dock-pop__row-label"><strong>Cabin</strong></div>' +
        '<div class="dock-pop__cabins">' +
        CABINS.map(function (c) {
          return '<button type="button" class="dock-pop__chip' + (cabinInput.value === c[0] ? " is-on" : "") + '" data-cabin="' + c[0] + '">' + c[1] + "</button>";
        }).join("") +
        '</div><button type="button" class="dock-pop__done">Done</button></div>';
      pop.querySelectorAll("[data-d]").forEach(function (btn) {
        btn.addEventListener("click", function () {
          adultsInput.value = String(Math.max(1, Math.min(9, n + Number(btn.getAttribute("data-d")))));
          syncFaces();
          paint();
        });
      });
      pop.querySelectorAll("[data-cabin]").forEach(function (btn) {
        btn.addEventListener("click", function () {
          cabinInput.value = btn.getAttribute("data-cabin");
          syncFaces();
          paint();
        });
      });
      pop.querySelector(".dock-pop__done").addEventListener("click", closePop);
    }
    paint();
  }

  /* Airport suggest */
  function localAirports(q) {
    var needle = String(q || "").trim().toLowerCase();
    var rows = AIRPORTS.map(function (a) {
      return { code: a[0], city: a[1], name: a[2], country: a[3] };
    });
    if (!needle) return rows.slice(0, 8);
    if (/^[a-z]{3}$/.test(needle)) {
      var exact = rows.filter(function (a) { return a.code.toLowerCase() === needle; });
      if (exact.length) return exact;
    }
    return rows
      .filter(function (a) {
        return (
          a.code.toLowerCase() === needle ||
          a.city.toLowerCase().indexOf(needle) === 0 ||
          a.name.toLowerCase().indexOf(needle) !== -1 ||
          a.country.toLowerCase().indexOf(needle) === 0
        );
      })
      .sort(function (a, b) { return (b.code.toLowerCase() === needle) - (a.code.toLowerCase() === needle); })
      .slice(0, 8);
  }

  function airportLabel(a) {
    return a.city + " (" + a.code + ")";
  }

  function paintAirports(rows, which, input, q) {
    if (!rows.length) {
      pop.innerHTML =
        '<p class="dock-pop__empty" style="padding:14px">' +
        (q ? "No airports match “" + escapeHtml(q) + "”." : "Try a city or airport code.") +
        "</p>";
      return;
    }
    pop.innerHTML =
      '<ul class="dock-pop__list" role="listbox">' +
      rows
        .map(function (a) {
          return (
            '<li><button type="button" class="dock-pop__opt" data-code="' + escapeHtml(a.code) +
            '" data-label="' + escapeHtml(airportLabel(a)) + '"><span class="dock-pop__copy"><span class="dock-pop__city">' +
            escapeHtml(a.city) + '</span><span class="dock-pop__meta">' +
            escapeHtml([a.name, a.country].filter(Boolean).join(" · ")) +
            '</span></span><span class="dock-pop__code">' + escapeHtml(a.code) + "</span></button></li>"
          );
        })
        .join("") +
      "</ul>";
    pop.querySelectorAll(".dock-pop__opt").forEach(function (btn) {
      btn.addEventListener("mousedown", function (ev) { ev.preventDefault(); });
      btn.addEventListener("click", function () {
        picked[which] = btn.getAttribute("data-code");
        input.value = btn.getAttribute("data-label");
        closePop();
        if (which === "from" && !picked.to) toInput.focus();
        else if (which === "to" && !departInput.value) departFace.click();
      });
    });
  }

  function renderAirports(which) {
    var input = which === "from" ? fromInput : toInput;
    var q = input.value.trim();
    // A label like "Mumbai (BOM)" means the airport is already chosen; show the full list again.
    var needle = picked[which] && q === q.replace(/\s*\(.*\)$/, "") + " (" + picked[which] + ")" ? "" : q;
    openPop("suggest", input);
    var local = localAirports(needle);
    paintAirports(local, which, input, needle);
    if (needle.length < 2) return;
    var req = ++state.req;
    fetch("/api/flights/airports?q=" + encodeURIComponent(needle) + "&limit=8", {
      credentials: "same-origin",
      headers: { Accept: "application/json" },
    })
      .then(function (r) { return r.json().catch(function () { return {}; }); })
      .then(function (data) {
        if (req !== state.req || state.kind !== "suggest") return;
        var items = data.airports || data.choices || data.results || [];
        var seen = {};
        var rows = local.slice();
        var exact = /^[A-Za-z]{3}$/.test(needle);
        rows.forEach(function (a) { seen[a.code] = 1; });
        (Array.isArray(items) ? items : []).forEach(function (a) {
          var code = String(a.code || a.iata || a.id || "").toUpperCase();
          if (!/^[A-Z]{3}$/.test(code) || seen[code]) return;
          if (exact && code !== needle.toUpperCase()) return;
          seen[code] = 1;
          rows.push({
            code: code,
            city: a.city || a.city_name || a.name || code,
            name: a.name || a.label || "",
            country: a.country || "",
          });
        });
        paintAirports(rows.slice(0, 8), which, input, needle);
        requestAnimationFrame(function () {
          if (state.kind === "suggest") placePop(input);
        });
      })
      .catch(function () {});
  }

  function resolveCode(which) {
    var input = which === "from" ? fromInput : toInput;
    var raw = input.value.trim();
    if (!raw) return "";
    var paren = raw.match(/\(([A-Za-z]{3})\)\s*$/);
    if (paren) return paren[1].toUpperCase();
    if (/^[A-Za-z]{3}$/.test(raw)) return raw.toUpperCase();
    if (picked[which] && raw.toLowerCase().indexOf(picked[which].toLowerCase()) !== -1) return picked[which];
    var hits = localAirports(raw).filter(function (a) { return a.city.toLowerCase() === raw.toLowerCase(); });
    return hits.length ? hits[0].code : "";
  }

  function swap() {
    var a = fromInput.value;
    fromInput.value = toInput.value;
    toInput.value = a;
    var p = picked.from;
    picked.from = picked.to;
    picked.to = p;
    closePop();
  }

  function submit(ev) {
    ev.preventDefault();
    var from = resolveCode("from");
    var to = resolveCode("to");
    if (!from) return setStatus("Choose where you’re flying from.", "error"), fromInput.focus();
    if (!to) return setStatus("Choose where you’re flying to.", "error"), toInput.focus();
    if (from === to) return setStatus("Pick two different airports.", "error");
    if (!departInput.value) return setStatus("Choose a departure date.", "error"), departFace.click();
    if (state.trip === "round" && !returnInput.value) {
      return setStatus("Choose a return date.", "error"), returnFace.click();
    }
    setStatus("");
    var q = new URLSearchParams({
      from: from,
      to: to,
      depart: departInput.value,
      adults: adultsInput.value || "1",
      cabin: cabinInput.value || "ECONOMY",
      trip: state.trip,
    });
    if (state.trip === "round") q.set("return", returnInput.value);
    try {
      var sid = sessionStorage.getItem("itinero_vero_ask_sid");
      var cap = sessionStorage.getItem("itinero_vero_ask_cap");
      if (sid && cap) {
        fetch("/api/aero/observe", {
          method: "POST",
          headers: { Accept: "application/json", "Content-Type": "application/json" },
          body: JSON.stringify({
            session_id: sid,
            capability: cap,
            observation: {
              type: "search",
              search: {
                origin: from,
                destination: to,
                depart_date: departInput.value,
                return_date: state.trip === "round" ? returnInput.value : undefined,
                adults: Number(adultsInput.value || 1),
                cabin: cabinInput.value || "ECONOMY",
              },
            },
          }),
        }).catch(function () {});
      }
    } catch (e) {}
    location.href = "/flights/results/?" + q.toString();
  }

  function prefillFromQuery() {
    var q = new URLSearchParams(location.search);
    function seed(which, input, param) {
      var code = String(q.get(param) || "").toUpperCase();
      if (!/^[A-Z]{3}$/.test(code)) return false;
      var hit = AIRPORTS.filter(function (a) { return a[0] === code; })[0];
      picked[which] = code;
      input.value = hit ? hit[1] + " (" + code + ")" : code;
      return true;
    }
    seed("from", fromInput, "from");
    seed("to", toInput, "to");
    if (q.get("depart")) departInput.value = q.get("depart");
    if (q.get("return")) returnInput.value = q.get("return");
    var adults = parseInt(q.get("adults"), 10);
    if (adults >= 1) adultsInput.value = String(Math.min(9, adults));
    var cabin = String(q.get("cabin") || "").toUpperCase();
    if (CABINS.some(function (c) { return c[0] === cabin; })) cabinInput.value = cabin;
    return q.get("trip") === "round" || !!q.get("return");
  }

  function seedHomeAirport() {
    if (fromInput.value) return;
    var loc = window.ItineroLocale && window.ItineroLocale.get && window.ItineroLocale.get();
    var code = String((loc && loc.airport) || "").toUpperCase();
    if (!/^[A-Z]{3}$/.test(code) || fromInput.value) return;
    var hit = AIRPORTS.filter(function (a) { return a[0] === code; })[0];
    picked.from = code;
    fromInput.value = hit ? hit[1] + " (" + code + ")" : code;
  }

  function init() {
    var round = prefillFromQuery();
    if (!departInput.value) departInput.value = addDays(isoDate(new Date()), 14);
    setTrip(round ? "round" : "oneway");

    document.querySelectorAll("#fl-trip [data-trip]").forEach(function (btn) {
      btn.addEventListener("click", function () { setTrip(btn.getAttribute("data-trip")); });
    });
    document.getElementById("fl-swap").addEventListener("click", function (ev) {
      ev.preventDefault();
      swap();
    });
    departFace.addEventListener("click", function () { state.calMonth = null; renderCalendar(departFace); });
    returnFace.addEventListener("click", function () { state.calMonth = null; renderCalendar(returnFace); });
    paxFace.addEventListener("click", function () { renderPax(paxFace); });
    [["from", fromInput], ["to", toInput]].forEach(function (pair) {
      var which = pair[0];
      var input = pair[1];
      input.addEventListener("focus", function () { renderAirports(which); });
      input.addEventListener("input", function () {
        picked[which] = "";
        renderAirports(which);
      });
      input.addEventListener("keydown", function (ev) {
        if (ev.key !== "Enter") return;
        var first = pop.querySelector(".dock-pop__opt");
        if (!pop.hidden && state.kind === "suggest" && first) {
          ev.preventDefault();
          first.click();
        }
      });
    });
    form.addEventListener("submit", submit);
    document.addEventListener("mousedown", function (ev) {
      if (pop.hidden) return;
      if (pop.contains(ev.target) || (ev.target.closest && ev.target.closest(".cell"))) return;
      closePop();
    });
    document.addEventListener("keydown", function (ev) {
      if (ev.key === "Escape") closePop();
    });
    window.addEventListener("resize", closePop);

    var ready = window.ItineroLocale && window.ItineroLocale.detect ? window.ItineroLocale.detect() : Promise.resolve();
    Promise.resolve(ready).then(seedHomeAirport, seedHomeAirport);
  }

  init();
})();

/* Popular routes: search about a month out */
(function () {
  var d = new Date();
  d.setDate(d.getDate() + 30);
  var iso = d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
  document.querySelectorAll(".fl-route").forEach(function (a) {
    a.href = "/flights/results/?from=" + a.dataset.from + "&to=" + a.dataset.to + "&depart=" + iso + "&adults=1&cabin=ECONOMY&trip=oneway";
  });
})();

/* Ask Vero card: chips and form hand the question to Vero */
(function () {
  var form = document.getElementById("fl-vero-form");
  if (!form) return;
  var input = document.getElementById("fl-vero-input");
  var chipRow = document.querySelector(".fl-vero__chips");
  var sets = [
    [
      ["Under 4 hours", "Quiet long weekend, under 4 hours, mid budget"],
      ["Warm in December", "Somewhere warm in December, direct flights, from my home airport"],
      ["Business, direct", "Business class to Singapore next month, direct only"],
      ["Cheapest month", "Cheapest month to fly from London to Tokyo"],
    ],
    [
      ["Direct only", "Direct flights from my home airport, mid budget"],
      ["With a meal", "A flight that includes a meal, under 8 hours"],
      ["Weekend break", "Somewhere nearby for a long weekend"],
      ["Avoid red-eyes", "Daytime flights only, no red-eyes"],
    ],
    [
      ["Family trip", "Family-friendly destination, under 6 hours"],
      ["Warm now", "Somewhere warm this month, direct if possible"],
      ["Short hop", "Under 3 hours from my home airport"],
      ["Best month", "Cheapest month to fly to Europe"],
    ],
  ];
  var placeholders = [
    "Warm, direct, under 8 hours",
    "Without stops, with a meal…",
    "Family trip, under 6 hours…",
  ];
  function go(q) {
    q = String(q || "").trim();
    location.href = "/vero/?q=" + encodeURIComponent(q);
  }
  function paint(index) {
    if (!chipRow) return;
    chipRow.replaceChildren();
    sets[index].forEach(function (pair) {
      var b = document.createElement("button");
      b.type = "button";
      b.textContent = pair[0];
      b.setAttribute("data-invite", pair[1]);
      b.addEventListener("click", function () { go(pair[1]); });
      chipRow.appendChild(b);
    });
    if (input && !input.value) input.placeholder = placeholders[index];
  }
  form.addEventListener("submit", function (e) { e.preventDefault(); go(input.value); });
  paint(0);
  var i = 0;
  setInterval(function () {
    if (input && document.activeElement === input) return;
    i = (i + 1) % sets.length;
    paint(i);
  }, 7000);
})();

