/* Below-hero for flights / hotels / experiences.
   Lists + one editorial photo per page. AI uses the shared aurora. */

.xb .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.xb {
