}

.xb-wrap {
  width: min(100%, 1180px);
  margin: 0 auto;
  padding: 56px 24px 12px;
  scroll-margin-top: 80px;
}

.xb > .xb-wrap:first-child {
  padding-top: 80px;
}

.xb-head { margin: 0 0 22px; }

.xb-head h2 {
  margin: 0;
  color: var(--xb-navy);
  font-size: clamp(1.25rem, 2.2vw, 1.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
}

.xb-head p {
  margin: 6px 0 0;
  max-width: 58ch;
  color: var(--xb-muted);
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.35;
}

/* Shared aurora ask — matches insight-suggest / vero-cta */
.xb .xb-ai.ai {
  padding: 22px 22px 20px;
}

.xb-ai__kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0 0 10px;
  color: var(--ai-muted, #c2500c);
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.xb-ai h2 {
  margin: 0;
  color: var(--xb-navy);
  font-size: clamp(1.2rem, 2vw, 1.45rem);
  font-weight: 800;
  letter-spacing: -0.03em;
}

.xb-ai > p {
  margin: 6px 0 0;
  max-width: 52ch;
  color: var(--xb-muted);
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.4;
}

.xb-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 16px 0 12px;
}

.xb-chips button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid color-mix(in srgb, var(--ai-lilac, #f97211) 55%, #fff);
  border-radius: 999px;
  background: #fff;
  color: var(--xb-navy);
  font: inherit;
  font-size: 0.84rem;
  font-weight: 650;
  cursor: pointer;
}

.xb-chips button:hover {
  border-color: var(--ai-pink, #fb9a4d);
  color: var(--ai-ink, #9a3a06);
}

.xb-ai__form {
  display: flex;
  gap: 8px;
  min-height: 50px;
  padding: 6px 6px 6px 16px;
  border: 1px solid color-mix(in srgb, var(--ai-lilac, #f97211) 40%, #e2e8f0);
  border-radius: 14px;
  background: #fff;
}

.xb-ai__form:focus-within {
  border-color: #d8b4fe;
  box-shadow: 0 0 0 4px rgba(249, 114, 17, 0.12);
}

.xb-ai__form input {
  flex: 1;
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--xb-navy);
  font: inherit;
  font-size: 0.95rem;
