  display: grid;
  border-top: 1px solid var(--xb-line);
}

.xb-line {
  display: grid;
  grid-template-columns: minmax(8.5rem, 11rem) minmax(0, 1fr) auto auto;
  gap: 12px 18px;
  align-items: center;
  min-height: 64px;
  padding: 12px 4px;
  border-bottom: 1px solid var(--xb-line);
  text-decoration: none;
  color: inherit;
}

.xb-line:hover { background: color-mix(in srgb, var(--xb-navy) 3%, transparent); }

.xb-line:focus-visible {
  outline: 2px solid var(--accent, #f97211);
  outline-offset: 2px;
}

.xb-pair {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--xb-navy);
  font-size: 1.02rem;
  font-weight: 800;
  letter-spacing: 0.04em;
}

.xb-pair i {
  flex: 1;
  max-width: 36px;
  height: 1px;
  background: #cbd5e1;
  position: relative;
}

.xb-pair i::after {
  content: "";
  position: absolute;
  top: 50%;
  right: -1px;
  width: 6px;
  height: 6px;
  border: 1.5px solid #94a3b8;
  border-left: 0;
  border-bottom: 0;
  transform: translateY(-50%) rotate(45deg);
}

.xb-line strong {
  color: var(--xb-ink);
  font-size: 0.98rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.xb-line em {
  font-style: normal;
  color: var(--xb-muted);
  font-size: 0.8rem;
  font-weight: 650;
}

.xb-line small {
  color: var(--accent, #f97211);
  font-size: 0.78rem;
  font-weight: 750;
  white-space: nowrap;
}

/* Mood / hop / jump rows */
.xb-pick {
  display: grid;
  gap: 0;
  border-top: 1px solid var(--xb-line);
}

.xb-pick a {
  display: grid;
  grid-template-columns: 7.5rem minmax(0, 1fr) auto;
  gap: 12px 16px;
  align-items: baseline;
  padding: 16px 4px;
  border-bottom: 1px solid var(--xb-line);
  text-decoration: none;
  color: inherit;
}

.xb-pick a:hover { background: color-mix(in srgb, var(--xb-navy) 3%, transparent); }

.xb-pick em {
  font-style: normal;
  color: var(--xb-muted);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.xb-pick strong {
  display: block;
  color: var(--xb-navy);
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: -0.03em;
}

.xb-pick span {
  display: block;
  margin-top: 2px;
  color: var(--xb-muted);
  font-size: 0.88rem;
  font-weight: 500;
}

.xb-pick small {
  color: var(--accent, #f97211);
  font-size: 0.78rem;
  font-weight: 750;
  white-space: nowrap;
}

/* One editorial photo + list (unique per page) */
.xb-split {
  display: grid;
  grid-template-columns: minmax(0, 0.92fr) minmax(0, 1.08fr);
  gap: 28px;
  align-items: stretch;
}

.xb-split__photo {
  position: relative;
  min-height: 280px;
  overflow: hidden;
  border-radius: 8px;
  background: #0b1a30;
}

.xb-split__photo img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.xb-split__photo figcaption {
  position: absolute;
  left: 14px;
  bottom: 12px;
  margin: 0;
  color: rgba(255, 255, 255, 0.88);
  font-size: 0.75rem;
  font-weight: 650;
}

.xb-cities {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0 24px;
  border-top: 1px solid var(--xb-line);
}

.xb-cities a {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 4px;
  border-bottom: 1px solid var(--xb-line);
  text-decoration: none;
  color: inherit;
}

.xb-cities a:hover { color: var(--xb-navy); }

.xb-cities strong {
  font-size: 1rem;
  font-weight: 750;
  letter-spacing: -0.02em;
}

.xb-cities em {
  font-style: normal;
  color: var(--xb-muted);
  font-size: 0.78rem;
  font-weight: 600;
}

html[data-theme="dark"] .xb-head h2,
html[data-theme="dark"] .xb-ai h2,
html[data-theme="dark"] .xb-pair,
html[data-theme="dark"] .xb-line strong,
html[data-theme="dark"] .xb-pick strong,
html[data-theme="dark"] .xb-cities strong {
