}

html[data-theme="dark"] .xb-ai,
html[data-theme="dark"] .xb-ai__form,
html[data-theme="dark"] .xb-chips button {
  background: var(--card, #111827);
}

html[data-theme="dark"] .xb-ai__form input,
html[data-theme="dark"] .xb-chips button {
  color: var(--ink, #e2e8f0);
}

/* Hotels cinema — live bookable hotel film after the hero */
.xb.xb--hotels {
  padding: 0;
}

.xb-cinema {
  position: relative;
  background: #05080d;
  color: #fff;
}

.xb-cinema__stage {
  position: relative;
  min-height: min(78vh, 820px);
  height: min(78vh, 820px);
  overflow: hidden;
  background: #000;
  cursor: pointer;
}

.xb-film__layers,
.xb-film__layer,
.xb-film__vid,
.xb-film__vignette {
  position: absolute;
  inset: 0;
}

.xb-film__layer,
.xb-film__vid {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.xb-film__layer {
  opacity: 0;
  transform: scale(1.04);
  transition: opacity 1.15s ease;
}

.xb-film__layer.is-on {
  opacity: 1;
}

.xb-film__layer--0.is-on {
  animation: xbKenA 9s ease-out forwards;
}

.xb-film__layer--1.is-on {
  animation: xbKenB 9s ease-out forwards;
}

.xb-film__layer--2.is-on {
  animation: xbKenC 9s ease-out forwards;
}

@keyframes xbKenA {
  from { transform: scale(1.02) translate3d(0, 0, 0); }
  to { transform: scale(1.16) translate3d(-3%, 2%, 0); }
}

@keyframes xbKenB {
  from { transform: scale(1.12) translate3d(-2%, 0, 0); }
  to { transform: scale(1.03) translate3d(2%, 1%, 0); }
}

@keyframes xbKenC {
  from { transform: scale(1.04) translate3d(0, 2%, 0); }
  to { transform: scale(1.14) translate3d(1%, -2%, 0); }
}

.xb-film__vignette {
  background:
    linear-gradient(180deg, rgba(5, 8, 13, 0.28) 0%, transparent 28%, transparent 46%, rgba(5, 8, 13, 0.88) 100%),
    linear-gradient(90deg, rgba(5, 8, 13, 0.45) 0%, transparent 38%, rgba(5, 8, 13, 0.35) 100%);
  pointer-events: none;
}

.xb-cinema__live {
  position: absolute;
  top: 76px;
  left: 24px;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(5, 8, 13, 0.42);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.xb-cinema__live i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #fb7185;
  box-shadow: 0 0 0 0 rgba(251, 113, 133, 0.65);
  animation: xbPulse 1.6s ease-out infinite;
}

@keyframes xbPulse {
  0% { box-shadow: 0 0 0 0 rgba(251, 113, 133, 0.65); }
  70% { box-shadow: 0 0 0 8px rgba(251, 113, 133, 0); }
  100% { box-shadow: 0 0 0 0 rgba(251, 113, 133, 0); }
}

.xb-film__hud {
  position: absolute;
  left: 24px;
  right: 240px;
  bottom: 28px;
  z-index: 3;
  max-width: 640px;
}

.xb-film__kind {
  margin: 0 0 8px;
  color: #ffd9b3;
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.xb-film__hud h2 {
  margin: 0;
  color: #fff;
  font-size: clamp(1.8rem, 4vw, 3.1rem);
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1.05;
  text-shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
}

.xb-film__meta,
.xb-film__story {
  margin: 10px 0 0;
  color: rgba(255, 255, 255, 0.82);
  font-size: 0.98rem;
  font-weight: 500;
  line-height: 1.4;
}

.xb-film__story {
  max-width: 52ch;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.xb-film__acts {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 18px;
}

.xb-film__go,
.xb-film__ctrl {
  min-height: 44px;
  padding: 0 18px;
  border-radius: 999px;
  font: inherit;
  font-size: 0.92rem;
  font-weight: 750;
  cursor: pointer;
}

.xb-film__go {
  display: inline-flex;
  align-items: center;
  background: #f97211;
  color: #fff;
  text-decoration: none;
  box-shadow: 0 10px 24px rgba(249, 114, 17, 0.28);
}

.xb-film__go:hover { filter: brightness(1.05); }

.xb-film__ctrl {
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
}

.xb-film__ctrl:hover { background: rgba(255, 255, 255, 0.16); }

.xb-film__bar {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 4;
  height: 3px;
  background: rgba(255, 255, 255, 0.16);
}

.xb-film__bar i {
  display: block;
  width: 0;
  height: 100%;
  background: #f97211;
}

@keyframes xbFilmBar {
  from { width: 0; }
  to { width: 100%; }
}

.xb-cast {
  position: absolute;
  top: 50%;
  right: 18px;
  z-index: 4;
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 72%;
  padding: 4px;
  overflow: auto;
  transform: translateY(-50%);
  scrollbar-width: none;
}

.xb-cast::-webkit-scrollbar { display: none; }

.xb-cast__item {
  position: relative;
  width: 92px;
  aspect-ratio: 9 / 14;
  padding: 0;
  overflow: hidden;
  border: 0;
  border-radius: 12px;
  background: #111827;
  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.35);
  cursor: pointer;
  opacity: 0.78;
}

.xb-cast__item img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.xb-cast__item span {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: grid;
  gap: 1px;
  padding: 20px 7px 8px;
  background: linear-gradient(180deg, transparent, rgba(0, 0, 0, 0.82));
  color: #fff;
  text-align: left;
}

.xb-cast__item em {
  font-style: normal;
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.7);
}

.xb-cast__item strong {
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: -0.02em;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.xb-cast__item.is-on {
  opacity: 1;
  outline: 2px solid #f97211;
  outline-offset: 2px;
}

.xb.xb--hotels .xb-wrap:first-of-type {
  padding-top: 56px;
}

@media (prefers-reduced-motion: reduce) {
  .xb-film__layer--0.is-on,
  .xb-film__layer--1.is-on,
  .xb-film__layer--2.is-on,
  .xb-cinema__live i,
  .xb-film__bar i {
    animation: none !important;
  }
}

@media (max-width: 860px) {
  .xb-split,
  .xb-line,
  .xb-pick a,
  .xb-cities {
    grid-template-columns: 1fr;
  }
  .xb-split__photo { min-height: 200px; }
  .xb-line em { display: none; }

  .xb-cinema__stage {
    height: auto;
    min-height: 78vh;
  }

  .xb-film__hud {
    right: 16px;
    left: 16px;
    bottom: 118px;
  }

  .xb-cinema__live { left: 16px; top: 72px; }

  .xb-cast {
    top: auto;
    right: 0;
    bottom: 14px;
    left: 0;
    max-height: none;
    flex-direction: row;
    padding: 0 16px;
    transform: none;
    overflow-x: auto;
  }

  .xb-cast__item { flex: 0 0 76px; width: 76px; }
}

